def find_captures(moves):
    """Indices of moves that capture material."""
    return [i for i, move in enumerate(moves) if "x" in move]


def find_checks(moves):
    """Indices of moves that deliver check or mate."""
    return [i for i, move in enumerate(moves) if "+" in move or "#" in move]


def find_castling(moves):
    """Yield (index, move) for king-side or queen-side castling."""
    for i, move in enumerate(moves):
        if move.rstrip("+#") in ("O-O", "O-O-O"):
            yield i, move


def format_move_pairs(moves):
    """Yield '{index}: {move}' for every ply."""
    for i, move in enumerate(moves):
        yield "{0}: {1}".format(i, move)


def find_pawn_promotions(moves):
    """Indices of moves promoting a pawn."""
    return [i for i, move in enumerate(moves) if "=" in move]


def detect_repetition(moves):
    """Indices where a move repeats the same side's move from two full turns ago."""
    repeats = []
    for i, move in enumerate(moves):
        if i >= 4 and moves[i - 4] == move:
            repeats.append(i)
    return repeats


def generate_json(moves):
    """Yield one JSON-ready record per ply."""
    for i, move in enumerate(moves):
        yield {"ply": i, "move": move}


def find_blunders(moves, engine_evals):
    """Yield (index, move) where the evaluation drops by more than 2.0 pawns."""
    if len(engine_evals) != len(moves):
        raise ValueError("engine_evals must be parallel to moves")
    for i, move in enumerate(moves):
        if i and engine_evals[i - 1] - engine_evals[i] > 2.0:
            yield i, move


def report(moves, engine_evals):
    """Build a human-readable summary of the move sequence."""
    lines = list(format_move_pairs(moves))
    lines.append("captures: " + str(find_captures(moves)))
    lines.append("checks: " + str(find_checks(moves)))
    lines.append("promotions: " + str(find_pawn_promotions(moves)))
    lines.append("repetitions: " + str(detect_repetition(moves)))
    for index, move in find_castling(moves):
        lines.append("castling at ply {0}: {1}".format(index, move))
    for index, move in find_blunders(moves, engine_evals):
        lines.append("blunder at ply {0}: {1}".format(index, move))
    return "\n".join(lines)


if __name__ == "__main__":
    game = ["e4", "e5", "Nf3", "Nc6", "Bb5", "a6", "Bxc6", "dxc6",
            "O-O", "Nf6", "Nc3", "Bg4", "h3", "Bxf3", "Qxf3", "Qd7"]
    evals = [0.2, 0.1, 0.3, 0.2, 0.3, 0.2, 0.4, 0.3,
             0.5, 0.4, 0.5, 0.4, 0.6, -2.1, 0.7, 0.6]
    print(report(game, evals))
    for record in generate_json(game[:4]):
        print(record)

