def sum_list(numbers):
    total = 0
    for index, value in enumerate(numbers):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("element at position %d is not a number: %r" % (index, value))
        total += value
    return total


def parse_row(text):
    tokens = text.split(",")
    numbers = []
    for position, token in enumerate(tokens):
        cleaned = token.strip()
        if not cleaned:
            continue
        try:
            numbers.append(float(cleaned) if "." in cleaned else int(cleaned))
        except ValueError:
            raise ValueError("field %d of %r is not numeric" % (position, text))
    return numbers


def running_totals(numbers):
    totals = []
    for index, value in enumerate(numbers):
        previous = totals[index - 1] if index else 0
        totals.append(previous + value)
    return totals


def peak_index(totals):
    best = 0
    for index, value in enumerate(totals):
        if value > totals[best]:
            best = index
    return best


def format_row(numbers):
    pieces = []
    for index, value in enumerate(numbers):
        separator = "" if index == 0 else " + "
        pieces.append(separator + str(value))
    return "".join(pieces) if pieces else "(empty)"


def report(rows):
    lines = []
    grand_total = 0
    for row_index, text in enumerate(rows):
        numbers = parse_row(text)
        total = sum_list(numbers)
        grand_total += total
        lines.append("row %d: %s = %s" % (row_index + 1, format_row(numbers), total))
        totals = running_totals(numbers)
        if totals:
            peak = peak_index(totals)
            lines.append("    peak running total %s after %d terms" % (totals[peak], peak + 1))
    lines.append("grand total: %s" % grand_total)
    return lines


def main():
    rows = [
        "1, 2, 3, 4",
        "",
        "10, -10, 5",
        "2.5, 2.5",
    ]
    for line in report(rows):
        print(line)


if __name__ == "__main__":
    main()

