def find_max(numbers):
    """Return the largest value in a non-empty list of integers."""
    largest = numbers[0]
    for value in numbers:
        if value > largest:
            largest = value
    return largest


def find_max_index(numbers):
    """Return the position of the first occurrence of the largest value."""
    best_index = 0
    best_value = numbers[0]
    for index, value in enumerate(numbers):
        if value > best_value:
            best_index = index
            best_value = value
    return best_index


def all_max_indices(numbers):
    """Return every position holding the largest value."""
    peak = find_max(numbers)
    positions = []
    for index, value in enumerate(numbers):
        if value == peak:
            positions.append(index)
    return positions


def validate(numbers):
    """Raise a descriptive error if the input is not a non-empty integer list."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not numbers:
        raise ValueError("numbers must not be empty")
    for position, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("element %d is not an integer: %r" % (position, value))
    return numbers


def running_maxima(numbers):
    """Return the maximum seen after each element has been read."""
    maxima = []
    current = numbers[0]
    for value in numbers:
        if value > current:
            current = value
        maxima.append(current)
    return maxima


def format_report(numbers):
    """Build a human readable summary of where the maximum lives."""
    validate(numbers)
    peak = find_max(numbers)
    peak_at = find_max_index(numbers)
    ties = all_max_indices(numbers)
    maxima = running_maxima(numbers)
    lines = ["values: " + ", ".join(str(v) for v in numbers),
             "maximum %d at index %d" % (peak, peak_at),
             "all peak positions: " + ", ".join(str(p) for p in ties)]
    for step, current in enumerate(maxima):
        marker = "*" if step in ties else " "
        lines.append("%s step %d -> max so far %d" % (marker, step, current))
    return "\n".join(lines)


def main():
    datasets = [
        [10, 5, 20, 8],
        [7],
        [-4, -9, -1, -1],
        [3, 3, 3],
    ]
    for case_number, numbers in enumerate(datasets):
        print("case %d" % case_number)
        print(format_report(numbers))
        print()


if __name__ == "__main__":
    main()

