OPERATIONS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}

ALLOWED_CHARS = set("0123456789+-*/. ")


def simple_calculator(num1, operator, num2):
    operation = OPERATIONS.get(operator)
    if operation is None:
        return 'Error'
    if operator == '/' and num2 == 0:
        return 'Error'
    return operation(num1, num2)


def validate_characters(text):
    for position, char in enumerate(text):
        if char not in ALLOWED_CHARS:
            raise ValueError("invalid character %r at position %d" % (char, position))


def to_number(token):
    stripped = token.strip()
    if not stripped:
        raise ValueError("missing operand")
    if '.' in stripped:
        return float(stripped)
    return int(stripped)


def parse_expression(text):
    cleaned = text.strip()
    validate_characters(cleaned)
    for position, char in enumerate(cleaned):
        if position > 0 and char in OPERATIONS:
            return to_number(cleaned[:position]), char, to_number(cleaned[position + 1:])
    raise ValueError("no operator found in %r" % text)


def evaluate_all(expressions):
    results = []
    for raw in expressions:
        try:
            num1, operator, num2 = parse_expression(raw)
        except ValueError as exc:
            results.append((raw.strip(), str(exc)))
            continue
        results.append((raw.strip(), str(simple_calculator(num1, operator, num2))))
    return results


def format_report(results):
    rows = [("#", "EXPRESSION", "RESULT")]
    for number, (expression, value) in enumerate(results, start=1):
        rows.append((str(number), expression, value))
    widths = [0] * len(rows[0])
    for row in rows:
        for column, cell in enumerate(row):
            widths[column] = max(widths[column], len(cell))
    lines = []
    for row in rows:
        padded = []
        for column, cell in enumerate(row):
            padded.append(cell.ljust(widths[column]))
        lines.append("  ".join(padded).rstrip())
    return "\n".join(lines)


def main():
    expressions = ["10 + 5", "10 / 0", "7 * 6", "9.5 - 4", "-8 / 2", "3 ^ 4", "12 +"]
    print(format_report(evaluate_all(expressions)))


if __name__ == "__main__":
    main()

