    candidate = 2
    while candidate * candidate <= remaining:
        while remaining % candidate == 0:
            factors.append(candidate)
            remaining //= candidate
        candidate += 1 if candidate == 2 else 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def format_factorization(n):
    """Render n as a product of prime powers, e.g. 360 -> 2^3 * 3^2 * 5."""
    if n == 1:
        return "1"
    groups = []
    factors = prime_factors(n)
    for position in range(len(factors)):
        if position and factors[position] == factors[position - 1]:
            groups[-1][1] += 1
        else:
            groups.append([factors[position], 1])
    return " * ".join(str(p) if e == 1 else "{}^{}".format(p, e) for p, e in groups)


def render_table(rows):
    """Render rows of strings as a left-aligned text table."""
    widths = [0] * max(len(row) for row in rows)
    for row in rows:
        for column in range(len(row)):
            widths[column] = max(widths[column], len(row[column]))
    lines = []
    for row in rows:
        cells = [row[column].ljust(widths[column]) for column in range(len(row))]
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


def main():
    samples = [1, 2, 7, 10, 97, 360, 1001, 7919]
    rows = [["#", "n", "prime?", "factorization"]]
    for index in range(len(samples)):
        verdict = "yes" if is_prime(samples[index]) else "no"
        rows.append([str(index + 1), str(samples[index]), verdict, format_factorization(samples[index])])
    print(render_table(rows))
    small = primes_upto(50)
    print("\nPrimes up to 50:")
    for rank in range(len(small)):
        print("  {:>2}. {}".format(rank + 1, small[rank]))


if __name__ == "__main__":
    main()

