    return best_index


def largest_jump(readings):
    """Return (index, delta) for the biggest change between consecutive readings."""
    best = None
    for index, celsius in enumerate(readings):
        if index == 0:
            continue
        delta = celsius - readings[index - 1]
        if best is None or abs(delta) > abs(best[1]):
            best = (index, delta)
    return best


