            % (peak + 1, readings[peak], celsius_to_fahrenheit(readings[peak]))
        )
    jump = largest_jump(readings)
    if jump is not None:
        lines.append(
            "biggest change: reading %d shifted by %.2f C (%.2f F)"
            % (jump[0] + 1, jump[1], jump[1] * 9 / 5)
        )
    return lines


