def validate_lists(*lists):
    """Check that every argument really is a list before comparing them."""
    for position, candidate in enumerate(lists, 1):
        if not isinstance(candidate, list):
            raise TypeError(
                "argument %d must be a list, got %s" % (position, type(candidate).__name__)
            )


def first_positions(values):
    """Map each hashable value to the index where it first appears."""
    positions = {}
    for index, value in enumerate(values):
        if value not in positions:
            positions[value] = index
    return positions


def list_intersection(list1, list2):
    """Return the common elements of two lists, in the order of list1, without repeats."""
    validate_lists(list1, list2)
    second = set(list2)
    common = []
    seen = set()
    for value in list1:
        if value in second and value not in seen:
            seen.add(value)
            common.append(value)
    return common


def multi_intersection(lists):
    """Intersect any number of lists, keeping the order of the first one."""
    if not lists:
        return []
    result = list(lists[0])
    for other in lists[1:]:
        result = list_intersection(result, other)
        if not result:
            break
    return result


def intersection_rows(list1, list2):
    """Build one row per common element: rank, value, index in each input."""
    common = list_intersection(list1, list2)
    left = first_positions(list1)
    right = first_positions(list2)
    rows = []
    for rank, value in enumerate(common, 1):
        rows.append((rank, repr(value), left[value], right[value]))
    return rows


def format_report(list1, list2):
    """Render a small text report describing the intersection of two lists."""
    rows = intersection_rows(list1, list2)
    header = "%s & %s -> %s" % (list1, list2, list_intersection(list1, list2))
    lines = [header]
    if not rows:
        lines.append("  (no common elements)")
    for line_number, (rank, value, left_index, right_index) in enumerate(rows):
        marker = "*" if line_number == 0 else " "
        lines.append(
            "  %s #%d %s at list1[%d], list2[%d]" % (marker, rank, value, left_index, right_index)
        )
    return "\n".join(lines)


def main():
    pairs = [
        ([1, 2, 3], [3, 4, 5]),
        ([1, 2], [3, 4]),
        (["a", "b", "b", "c"], ["c", "b", "z"]),
        ([], [1, 2, 3]),
    ]
    for case_number, (left, right) in enumerate(pairs, 1):
        print("Case %d" % case_number)
        print(format_report(left, right))
    groups = [[1, 2, 3, 4], [2, 3, 4, 5], [3, 4, 9]]
