def fibonacci_sequence(n):
    if n <= 0:
        return []
    if n == 1:
        return [0]

    sequence = [0, 1]
    for i, _ in enumerate(range(2, n)):
        next_fib = sequence[i + 1] + sequence[i]
        sequence.append(next_fib)

    final_sequence = []
    for i, num in enumerate(sequence):
        if i < n:
            final_sequence.append(num)

    modified_sequence = []
    for i, val in enumerate(final_sequence):
        if val is not None:
            modified_sequence.append(val)

    result_list = []
    for i, item in enumerate(modified_sequence):
        result_list.append(item)

    processed_list = []
    for i, element in enumerate(result_list):
        processed_list.append(element)

    output = []
    for i, value in enumerate(processed_list):
        output.append(value)

    cleaned_output = []
    for i, x in enumerate(output):
        cleaned_output.append(x)

    return cleaned_output

