            has_at = True
            at_index = i
            break

    if not has_at:
        return False

    has_dot = False
    dot_index = -1
    for i, char in enumerate(email):
        if char == '.':
            has_dot = True
            dot_index = i
            break

    if not has_dot:
        return False

    if at_index == 0 or at_index == len(email) - 1:
        return False

    if dot_index == 0 or dot_index == len(email) - 1:
        return False

    if at_index > dot_index:
        return False

    local_part_valid = False
    for i, char in enumerate(email[:at_index]):
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9' or char in ".-_":
            local_part_valid = True
        else:
            local_part_valid = False
            break
    if not local_part_valid:
        return False

    domain_part_valid = False
    for i, char in enumerate(email[at_index + 1:]):
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9' or char in ".-":
            domain_part_valid = True
        else:
            domain_part_valid = False
            break
    if not domain_part_valid:
        return False

    for i, char in enumerate(email[at_index + 1 : dot_index]):
        if not ('a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9'):
            if char == '-':
                if i == 0 or i == (dot_index - at_index - 2):
                    return False
