import math


def _validate(numbers):
    values = list(numbers)
    if not values:
        raise ValueError("geometric mean requires at least one number")
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, value))
        if value <= 0:
            raise ValueError("element %d must be positive, got %r" % (index, value))
    return values


def geometric_mean(numbers):
    values = _validate(numbers)
    log_sum = math.fsum(math.log(value) for value in values)
    return math.exp(log_sum / len(values))


def running_geometric_means(numbers):
    values = _validate(numbers)
    means = []
    log_total = 0.0
    for index, value in enumerate(values):
        log_total += math.log(value)
        means.append(math.exp(log_total / (index + 1)))
    return means


def arithmetic_mean(numbers):
    values = _validate(numbers)
    return math.fsum(values) / len(values)


def spread_ratio(numbers):
    return geometric_mean(numbers) / arithmetic_mean(numbers)


def format_series(numbers):
    values = _validate(numbers)
    parts = []
    for index, value in enumerate(values):
        parts.append("x%d=%g" % (index, value))
    return ", ".join(parts)


def format_running_table(numbers):
    means = running_geometric_means(numbers)
    lines = []
    for index, mean in enumerate(means):
        lines.append("  n=%-3d gm=%.6f" % (index + 1, mean))
    return "\n".join(lines)


def main():
    datasets = [
        [2, 8],
        [1, 1, 1],
        [1, 3, 9, 27],
        [1.5, 2.5, 10.0],
        [100, 0.01],
    ]
    for index, data in enumerate(datasets):
        print("Dataset %d: %s" % (index + 1, format_series(data)))
        print("  geometric mean : %.6f" % geometric_mean(data))
        print("  arithmetic mean: %.6f" % arithmetic_mean(data))
        print("  gm / am ratio  : %.6f" % spread_ratio(data))
        print(format_running_table(data))

    bad_inputs = [[], [4, -1], [2, "8"]]
    for index, candidate in enumerate(bad_inputs):
        try:
            geometric_mean(candidate)
        except (TypeError, ValueError) as error:
            print("Rejected input %d (%r): %s" % (index, candidate, error))


if __name__ == "__main__":
    main()

