    if guess > secret_number:
        return 'Too high'
    if guess < secret_number:
        return 'Too low'
    return 'Correct!'


def parse_guesses(raw_guesses):
    """Turn user supplied text into integers, reporting the bad entries."""
    numbers = []
    problems = []
    for position, raw in enumerate(raw_guesses, start=1):
        text = str(raw).strip()
        try:
            numbers.append(int(text))
        except ValueError:
            problems.append('entry %d (%r) is not a whole number' % (position, text))
    return numbers, problems


def play_round(secret_number, guesses):
    """Evaluate every guess, stopping at the first correct one."""
    results = []
    for attempt, guess in enumerate(guesses, start=1):
        verdict = guess_number(secret_number, guess)
        results.append((attempt, guess, verdict))
        if verdict == 'Correct!':
