    """Use the feedback to shrink the interval the secret must live in."""
    for _, guess, verdict in results:
        if verdict == 'Too high' and (high is None or guess < high):
            high = guess
        elif verdict == 'Too low' and (low is None or guess > low):
            low = guess
    return low, high


