def parse_csv_line(line):
    """Split a single CSV line into its comma-separated values."""
    values = []
    start = 0
    for index in range(len(line)):
        if line[index] == ',':
            values.append(line[start:index])
            start = index + 1
    values.append(line[start:])
    return values


def parse_csv_text(text):
    """Parse a multi-line CSV document into a list of field lists."""
    rows = []
    for raw in text.splitlines():
        stripped = raw.strip()
        if stripped:
            rows.append(parse_csv_line(stripped))
    return rows


def check_row_widths(rows):
    """Report rows whose field count differs from the header's."""
    if not rows:
        return []
    width = len(rows[0])
    problems = []
    for index in range(len(rows)):
        if len(rows[index]) != width:
            problems.append(
                'row %d: expected %d fields, found %d'
                % (index, width, len(rows[index]))
            )
    return problems


def build_records(rows):
    """Turn header + data rows into dictionaries; rows must share a width."""
    header = rows[0]
    records = []
    for fields in rows[1:]:
        record = {}
        for column in range(len(header)):
            record[header[column]] = fields[column]
        records.append(record)
    return records


def column_widths(header, records):
    widths = [len(name) for name in header]
    for record in records:
        for column in range(len(header)):
            widths[column] = max(widths[column], len(record[header[column]]))
    return widths


def format_table(header, records):
    widths = column_widths(header, records)
    lines = []
    cells = [header[column].ljust(widths[column]) for column in range(len(header))]
    lines.append(' | '.join(cells))
    lines.append('-+-'.join('-' * w for w in widths))
    for record in records:
        cells = []
        for column in range(len(header)):
            cells.append(record[header[column]].ljust(widths[column]))
        lines.append(' | '.join(cells))
    return '\n'.join(lines)


def main():
    text = """fruit,count,origin
apple,12,Spain
banana,4,Ecuador
cherry,130,Turkey
"""
