import string

ALPHABET = string.ascii_lowercase + string.ascii_uppercase + string.digits
SAMPLE_LENGTHS = [8, 12, 16]


def generate_password(length):
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(random.choice(ALPHABET) for _ in range(length))


def classify(char):
    if char in string.ascii_lowercase:
        return "lowercase"
    if char in string.ascii_uppercase:
        return "uppercase"
    return "digit"


def positions_of_digits(password):
    found = []
    for index, char in enumerate(password):
        if char in string.digits:
            found.append(index)
    return found


def find_repeats(password):
    repeats = []
    for index, char in enumerate(password):
        if index and char == password[index - 1]:
            repeats.append((index, char))
    return repeats


def describe(password):
    counts = {"lowercase": 0, "uppercase": 0, "digit": 0}
    for char in password:
        counts[classify(char)] += 1
    return counts


