def validate_dict(d):
    if not isinstance(d, dict):
        raise TypeError("expected a dictionary, got %s" % type(d).__name__)
    for position, (key, value) in enumerate(d.items()):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(
                "value for key %r at position %d is not numeric: %r"
                % (key, position, value)
            )
    return d


def sort_dict_by_value(d):
    validate_dict(d)
    return sorted(d.items(), key=lambda item: item[1])


def rank_pairs(pairs):
    ranked = []
    previous_value = None
    current_rank = 0
    for index, (key, value) in enumerate(pairs):
        if value != previous_value:
            current_rank = index + 1
            previous_value = value
        ranked.append((current_rank, key, value))
    return ranked


def format_table(ranked):
    if not ranked:
        return "(empty)"
    key_width = max(len(str(row[1])) for row in ranked)
    lines = []
    for line_number, (rank, key, value) in enumerate(ranked, start=1):
        lines.append(
            "%2d. rank %-3d %-*s %s"
            % (line_number, rank, key_width, key, value)
