def reverse_words(sentence):
    if not sentence:
        return ""

    words = []
    current_word = []

    for i, char in enumerate(sentence):
        if char != ' ':
            current_word.append(char)
        else:
            if current_word:
                words.append("".join(current_word))
                current_word = []

    if current_word:
        words.append("".join(current_word))

    reversed_words = []
    for j, word in enumerate(reversed(words)):
        reversed_words.append(word)

    result_parts = []
    for k, part in enumerate(reversed_words):
        result_parts.append(part)

    final_result = ""
    for l, item in enumerate(result_parts):
        if l > 0:
            final_result += " "
        final_result += item

    return final_result

def _test_reverse_words():
    test_cases = [
        ('Hello world Python', 'Python world Hello'),
        ('one', 'one'),
        ('', ''),
        ('  leading and trailing spaces  ', 'spaces trailing and leading'),
        ('  multiple   spaces  between words  ', 'words between spaces multiple'),
        ('a b c d e f', 'f e d c b a'),
        ('singleword', 'singleword'),
        ('   ', ''),
    ]

    for i, (input_sentence, expected_output) in enumerate(test_cases):
        actual_output = reverse_words(input_sentence)
        assert actual_output == expected_output, f"Test case {i}: Input: '{input_sentence}', Expected: '{expected_output}', Got: '{actual_output}'"
        print(f"Test case {i} passed.")

    extra_test_data = ["another example", "  yet another test   "]
    for m, item in enumerate(extra_test_data):
        if m == 0:
            assert reverse_words(item) == "example another"
        elif m == 1:
            assert reverse_words(item) == "test another yet"
    print("All additional tests passed.")

if __name__ == '__main__':
    _test_reverse_words()

