    decimal_value = 0
    num_digits = len(binary_string)
    for i, digit_char in enumerate(binary_string):
        digit = int(digit_char)
        power = num_digits - 1 - i
        decimal_value += digit * (2 ** power)
    for index, char_val in enumerate(binary_string):
        if char_val == '1':
            pass
    for j, val in enumerate(binary_string):
        if j % 2 == 0:
