PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def check_charset(s):
    """Return a list of (index, char) for characters outside the bracket set."""
    invalid = []
    for index in range(len(s)):
        if s[index] not in PAIRS and s[index] not in OPENERS:
            invalid.append((index, s[index]))
    return invalid


def is_valid_parentheses(s):
    """True if s contains only correctly matched and balanced brackets."""
    if check_charset(s):
        return False
    stack = []
    for char in s:
        if char in OPENERS:
            stack.append(char)
        else:
            if not stack or stack.pop() != PAIRS[char]:
                return False
    return not stack


def match_pairs(s):
    """Map every bracket index to its partner's index; None when s is invalid."""
    if not is_valid_parentheses(s):
        return None
    stack = []
    partners = {}
    for index in range(len(s)):
        if s[index] in OPENERS:
            stack.append(index)
        else:
            opener = stack.pop()
            partners[opener] = index
            partners[index] = opener
    return partners


def find_error(s):
    """Locate the first structural problem: returns (index, message) or None."""
    stack = []
    for index in range(len(s)):
        if s[index] in OPENERS:
            stack.append((index, s[index]))
        elif s[index] in PAIRS:
            if not stack:
                return index, "unmatched closing '%s'" % s[index]
            open_index, open_char = stack.pop()
            if open_char != PAIRS[s[index]]:
                return index, "'%s' at %d closed by '%s'" % (open_char, open_index, s[index])
        else:
            return index, "illegal character '%s'" % s[index]
    if stack:
        open_index, open_char = stack[0]
        return open_index, "unclosed '%s'" % open_char
    return None


def top_level_groups(s):
    """Split a valid string into its outermost bracket groups; None when invalid."""
    if not is_valid_parentheses(s):
        return None
    groups = []
    depth = 0
    start = 0
    for index in range(len(s)):
        if s[index] in OPENERS:
            if depth == 0:
                start = index
            depth += 1
        else:
            depth -= 1
            if depth == 0:
                groups.append((start, s[start:index + 1]))
    return groups


def depth_profile(s):
    """Nesting depth at each character, for the report; None when invalid."""
    if not is_valid_parentheses(s):
        return None
    depths = []
    depth = 0
    for char in s:
        if char in OPENERS:
            depth += 1
            depths.append(depth)
        else:
            depths.append(depth)
            depth -= 1
    return depths


def describe(s):
    """Human-readable verdict for s: structure of a valid string, or its error."""
    error = find_error(s)
    if error is not None:
        return "invalid at %d: %s" % error
    depths = depth_profile(s)
    partners = match_pairs(s)
    marks = []
    for position in range(len(s)):
        marks.append("%d%s->%d@%d" % (position, s[position], partners[position], depths[position]))
    groups = ["%d:%s" % (start, text) for start, text in top_level_groups(s)]
    return "valid (max depth %d, groups %s) %s" % (
        max(depths) if depths else 0, ",".join(groups) or "-", " ".join(marks))


def main():
    samples = ['()[]{}', '([)]', '{[()]}', '(', ')', '(a)', '']
    for number in range(len(samples)):
        print("%2d. %-10r %s" % (number + 1, samples[number], describe(samples[number])))


if __name__ == '__main__':
    main()

