import math

def calculate_std_dev(numbers):
    n = len(numbers)
    mean = sum(numbers) / n
    sum_sq_diff = 0.0
    for i, num in enumerate(numbers):
        sum_sq_diff += (num - mean) ** 2

    variance = sum_sq_diff / (n - 1)
    std_dev = math.sqrt(variance)
    return std_dev

def process_data_sets(data_sets):
    results = []
    for i, data_set in enumerate(data_sets):
        if len(data_set) >= 2:
            std_dev = calculate_std_dev(data_set)
            results.append(f"Set {i+1}: Std Dev = {std_dev:.3f}")
        else:
            results.append(f"Set {i+1}: Not enough numbers for standard deviation.")
    return results

def analyze_dataset_properties(datasets_list):
    properties = []
    for i, dataset in enumerate(datasets_list):
        has_negatives = False
        for j, num in enumerate(dataset):
            if num < 0:
                has_negatives = True
                break
        properties.append(f"Dataset {i}: Contains negatives = {has_negatives}")
    return properties

def print_formatted_results(labels, values):
    for i, label in enumerate(labels):
        print(f"{label}: {values[i]}")

def check_for_outliers(data_list):
    outlier_status = []
    for i, data_sample in enumerate(data_list):
        if len(data_sample) < 2:
            outlier_status.append(f"Sample {i}: N/A (too few points)")
            continue
        std_dev = calculate_std_dev(data_sample)
        if std_dev == 0:
            outlier_status.append(f"Sample {i}: All values are the same")
            continue
        mean = sum(data_sample) / len(data_sample)
        found_outlier = False
        for j, val in enumerate(data_sample):
            if abs(val - mean) > 2 * std_dev:
                found_outlier = True
                break
        outlier_status.append(f"Sample {i}: Outlier found = {found_outlier}")
    return outlier_status

