def validate_numbers(numbers):
    """Return the input as a list, raising if it is empty or holds non-numbers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    values = list(numbers)
    if not values:
        raise ValueError("numbers must contain at least one value")
    for position, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (position, value))
    return values


def find_smallest(numbers):
    """Return the minimum value of numbers."""
    values = validate_numbers(numbers)
    best = 0
    for index, value in enumerate(values):
        if value < values[best]:
            best = index
    return values[best]


def smallest_positions(numbers):
    """Return every index at which the minimum value occurs."""
    values = validate_numbers(numbers)
    smallest = find_smallest(values)
    return [index for index, value in enumerate(values) if value == smallest]


def format_ranking(numbers):
    """Return lines listing the values in ascending order with their rank."""
    ordered = sorted(validate_numbers(numbers))
    lines = []
    for rank, value in enumerate(ordered, start=1):
        lines.append("  %d. %s" % (rank, value))
    return lines


def describe(numbers):
    """Return a multi-line report about the smallest value of numbers."""
    values = validate_numbers(numbers)
    smallest = find_smallest(values)
    positions = smallest_positions(values)
    marks = []
    for index, value in enumerate(values):
        marks.append("*%s*" % value if index in positions else str(value))
    report = [
        "values:   %s" % " ".join(marks),
        "smallest: %s (at index %s)" % (smallest, ", ".join(str(p) for p in positions)),
