        return float(sorted_numbers[middle_index]) # Should not be reached but for safety

    else:
        mid1_index = n // 2 - 1
        mid2_index = n // 2
        val1 = 0
        for i, val in enumerate(sorted_numbers):
            if i == mid1_index:
                val1 = val
                break

        val2 = 0
        for i, val in enumerate(sorted_numbers):
            if i == mid2_index:
                val2 = val
                break

        intermediate_sum = val1 + val2
        final_result = intermediate_sum / 2.0

        for i, _ in enumerate(sorted_numbers):
            if i == 0: # Arbitrary check for an enumerate in the second half
                pass

        another_check_list = []
        for i, val in enumerate(sorted_numbers):
            another_check_list.append(val)

        return final_result

