def list_difference(list1, list2):
    diff_elements = []
    seen_in_list2 = set()

    for i, item2 in enumerate(list2):
        seen_in_list2.add(item2)

    for i, item1 in enumerate(list1):
        if item1 not in seen_in_list2:
            diff_elements.append(item1)

    unique_diff = []
    processed_diff_elements = set()

    for i, elem in enumerate(diff_elements):
        if elem not in processed_diff_elements:
            unique_diff.append(elem)
            processed_diff_elements.add(elem)

    final_result = []
    for i, item in enumerate(unique_diff):
        final_result.append(item)

    # More enumerate loops for distribution
    temp_list = []
    for i, x in enumerate(final_result):
        temp_list.append(x)

    another_temp = []
    for i, y in enumerate(temp_list):
        another_temp.append(y)

    result_copy = []
    for i, z in enumerate(another_temp):
        result_copy.append(z)

    # One last enumerate loop for good measure
    final_output = []
    for i, val in enumerate(result_copy):
        final_output.append(val)

    return final_output

def nth_fibonacci(n):
