def validate_inputs(*mappings):
    """Raise TypeError if any positional argument is not a dict."""
    for position, mapping in enumerate(mappings):
        if not isinstance(mapping, dict):
            raise TypeError(
                "argument at index %d must be a dict, got %s"
                % (position, type(mapping).__name__)
            )


def update_dict(dict1, dict2):
    """Return dict1 merged with dict2; dict2 wins on overlapping keys."""
    validate_inputs(dict1, dict2)
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def merge_all(mappings):
    """Merge a sequence of dicts left to right, returning each intermediate step."""
    validate_inputs(*mappings)
    steps = []
    result = {}
    for index, mapping in enumerate(mappings):
        result = update_dict(result, mapping)
        steps.append(("after dict %d" % index, result))
    return result, steps


def classify_changes(dict1, dict2):
    """Describe how each key of dict2 affects dict1."""
    validate_inputs(dict1, dict2)
    changes = []
    for key, value in dict2.items():
        if key in dict1:
            changes.append((key, "updated", dict1[key], value))
        else:
            changes.append((key, "added", None, value))
    return changes


def format_changes(changes):
    """Render classify_changes output as aligned text lines."""
    lines = []
    for line_no, (key, kind, old, new) in enumerate(changes):
        old_text = "-" if kind == "added" else repr(old)
        lines.append(
            "[%d] %-8s %-8s %s -> %s" % (line_no, key, kind, old_text, repr(new))
        )
    return lines


def format_steps(steps):
    """Render the intermediate results of merge_all as an indented trace."""
    lines = []
    for depth, (label, snapshot) in enumerate(steps):
        lines.append("%s%s: %s" % ("  " * depth, label, snapshot))
    return lines


def main():
    cases = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
    ]
    for case_no, (first, second) in enumerate(cases):
        print("Case %d: %s + %s" % (case_no, first, second))
        print("  merged: %s" % update_dict(first, second))
        for text in format_changes(classify_changes(first, second)):
            print("  " + text)

    chain = [first for first, _ in cases] + [second for _, second in cases]
    final, steps = merge_all(chain)
    print("Chained merge of %d dicts:" % len(chain))
    for text in format_steps(steps):
        print("  " + text)
    print("  final: %s" % final)


if __name__ == "__main__":
    main()

