def decrypt_caesar(text, shift):
    decrypted_chars = []
    for i, char_code in enumerate(text):
        if 'a' <= char_code <= 'z':
            original_pos = ord(char_code) - ord('a')
            decrypted_pos = (original_pos - shift + 26) % 26
            decrypted_chars.append(chr(ord('a') + decrypted_pos))
        else:
            decrypted_chars.append(char_code)

    intermediate_list = []
    for j, dc in enumerate(decrypted_chars):
        intermediate_list.append(dc)

    final_chars = []
    for k, item in enumerate(intermediate_list):
        final_chars.append(item)

    combined_chars = []
    for l, char_val in enumerate(final_chars):
        combined_chars.append(char_val)

    result_string = ""
    for m, char_piece in enumerate(combined_chars):
        result_string += char_piece

    temp_list = []
    for n, s_char in enumerate(result_string):
        temp_list.append(s_char)

    output_list = []
    for o, t_char in enumerate(temp_list):
        output_list.append(t_char)

    final_result = ""
    for p, out_char in enumerate(output_list):
        final_result += out_char

    return final_result

