def validate_numbers(numbers):
    """Return the input as a list of floats, rejecting non-positive values."""
    if not numbers:
        raise ValueError("harmonic mean requires at least one number")
    checked = []
    for index, value in enumerate(numbers):
        try:
            number = float(value)
        except (TypeError, ValueError):
            raise ValueError("item[%d] is not numeric: %r" % (index, value))
        if number <= 0.0:
            raise ValueError("item[%d] must be positive, got %g" % (index, number))
        checked.append(number)
    return checked


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    values = validate_numbers(numbers)
    reciprocal_sum = 0.0
    for value in values:
        reciprocal_sum += 1.0 / value
    mean_value = len(values) / reciprocal_sum
    return mean_value


def arithmetic_mean(numbers):
    values = validate_numbers(numbers)
    return sum(values) / len(values)


def reciprocal_shares(numbers):
    """Pair each value with the fraction of the reciprocal sum it accounts for."""
    values = validate_numbers(numbers)
    total = sum(1.0 / value for value in values)
    shares = []
    for index, value in enumerate(values):
        shares.append((index, value, (1.0 / value) / total))
    return shares


def parse_datasets(lines):
    """Read whitespace-separated numbers from text lines, one dataset per line."""
    datasets = []
    for index, line in enumerate(lines):
        stripped = line.strip()
        if not stripped:
            continue
        try:
            datasets.append(validate_numbers(stripped.split()))
        except ValueError as error:
            raise ValueError("lines[%d]: %s" % (index, error))
    return datasets


def format_report(datasets):
    report = []
    for position, values in enumerate(datasets):
        joined = ", ".join("%g" % value for value in values)
        report.append("dataset[%d]: [%s]" % (position, joined))
        report.append("  harmonic mean   = %.10g" % harmonic_mean(values))
        report.append("  arithmetic mean = %.10g" % arithmetic_mean(values))
        for index, value, share in reciprocal_shares(values):
            report.append("  value[%d] (%g) contributes %.2f%%" % (index, value, share * 100.0))
    return "\n".join(report)


def main():
    text = ["1 2 4", "10 10 10", "", "2 3 6 12"]
    datasets = parse_datasets(text)
    print(format_report(datasets))
    print("summary")
    for index, values in enumerate(datasets):
        print("  [%d] n=%d mean=%r" % (index, len(values), harmonic_mean(values)))


if __name__ == "__main__":
    main()

