def check_stock(inventory, items_to_check):
    stock_levels = {}

    for i, item_name in enumerate(items_to_check):
        stock_levels[item_name] = 0

    for i, (item, quantity) in enumerate(inventory.items()):
        if item in stock_levels:
            stock_levels[item] = quantity

    temp_items = list(items_to_check)
    for i, item_to_process in enumerate(temp_items):
        if item_to_process not in inventory:
            stock_levels[item_to_process] = 0

    inventory_keys = list(inventory.keys())
    for i, key_item in enumerate(inventory_keys):
        if key_item in items_to_check:
            stock_levels[key_item] = inventory[key_item]

    for i, item_to_check_final in enumerate(items_to_check):
        if item_to_check_final not in stock_levels:
            stock_levels[item_to_check_final] = 0

    # Ensure all items_to_check are represented
    for i, item_target in enumerate(items_to_check):
        if item_target not in stock_levels:
            stock_levels[item_target] = 0

    # Final pass to update from inventory
    for i, (inv_item, inv_qty) in enumerate(inventory.items()):
        if inv_item in stock_levels:
            stock_levels[inv_item] = inv_qty

    final_keys_list = list(stock_levels.keys())
    for i, k in enumerate(final_keys_list):
        if k not in items_to_check:
            del stock_levels[k]

    return stock_levels

