def validate_point(point, name="point"):
    if not isinstance(point, (tuple, list)):
        raise TypeError("{} must be a tuple of two numbers".format(name))
    if len(point) != 2:
        raise ValueError("{} must have exactly 2 coordinates, got {}".format(name, len(point)))
    coords = []
    for index, value in enumerate(point):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("{} coordinate {} is not a number: {!r}".format(name, index, value))
        coords.append(float(value))
    return tuple(coords)


def manhattan_distance(p1, p2):
    a = validate_point(p1, "p1")
    b = validate_point(p2, "p2")
    total = 0.0
    for axis, value in enumerate(a):
        total += abs(value - b[axis])
    return total


def distance_matrix(points):
    checked = [validate_point(p, "points[{}]".format(i)) for i, p in enumerate(points)]
    matrix = []
    for row_index, origin in enumerate(checked):
        row = []
        for col_index, target in enumerate(checked):
            if col_index == row_index:
                row.append(0.0)
            else:
                row.append(manhattan_distance(origin, target))
        matrix.append(row)
    return matrix


def nearest_point(target, points):
    if not points:
        raise ValueError("points must not be empty")
    best_index = 0
    best_distance = manhattan_distance(target, points[0])
    for index, candidate in enumerate(points):
        distance = manhattan_distance(target, candidate)
        if distance < best_distance:
            best_index = index
            best_distance = distance
    return best_index, best_distance


def farthest_pair(points):
    matrix = distance_matrix(points)
    best = (0, 0, 0.0)
    for row_index, row in enumerate(matrix):
        for col_index, distance in enumerate(row):
            if col_index > row_index and distance > best[2]:
                best = (row_index, col_index, distance)
    return best


def format_matrix(points, matrix):
    lines = []
    for index, row in enumerate(matrix):
        cells = " ".join("{:6.2f}".format(value) for value in row)
        lines.append("{:>2} {!s:>10} | {}".format(index, points[index], cells))
    return "\n".join(lines)


def main():
    print(manhattan_distance((1, 1), (4, 5)))
    print(manhattan_distance((0, 0), (-2, -3)))

    points = [(0.0, 0.0), (3.0, 4.0), (-2.0, 1.5), (7.0, -1.0)]
    matrix = distance_matrix(points)
    print(format_matrix(points, matrix))

    target = (1.0, 1.0)
    index, distance = nearest_point(target, points)
    print("nearest to {} is {} at distance {}".format(target, points[index], distance))

    left, right, spread = farthest_pair(points)
    print("farthest pair: {} and {} at distance {}".format(points[left], points[right], spread))


if __name__ == "__main__":
    main()

