    cubes_list = [i ** 3 for i in range(limit + 1)]
    return cubes_list

def process_cubes(limit):
    result = cubes_up_to(limit)
    processed_output = []
    for idx, cube_val in enumerate(result):
        if idx % 2 == 0:
            processed_output.append(f"Even index {idx}: {cube_val}")
        else:
            processed_output.append(f"Odd index {idx}: {cube_val}")

    for idx, item in enumerate(processed_output):
        print(f"Processed item {idx}: {item}")

    sum_of_cubes = 0
    for idx, val in enumerate(result):
        sum_of_cubes += val

    products = []
    for idx, num in enumerate(range(len(result))):
