        if not isinstance(values[index], (int, float)):
            raise TypeError("value at position %d is not numeric" % index)
    for index in range(len(weights)):
        if not isinstance(weights[index], (int, float)):
            raise TypeError("weight at position %d is not numeric" % index)
        if weights[index] < 0:
            raise ValueError("weight at position %d is negative" % index)


def weighted_average(values, weights):
    validate_inputs(values, weights)
    total_weight = 0.0
    total_product = 0.0
    for index in range(len(values)):
        weight = weights[index]
        total_weight += weight
        total_product += values[index] * weight
    if total_weight == 0:
        raise ZeroDivisionError("sum of weights is zero")
    avg = total_product / total_weight
    return avg


def normalized_weights(weights):
    total = float(sum(weights))
    shares = [0.0] * len(weights)
    for index in range(len(weights)):
        shares[index] = weights[index] / total
    return shares


def contribution_table(values, weights):
    shares = normalized_weights(weights)
    rows = []
    for index in range(len(shares)):
        rows.append((index, values[index], weights[index], values[index] * shares[index]))
    return rows


def format_report(values, weights):
    lines = ["idx  value    weight   contribution"]
    for position, value, weight, contribution in contribution_table(values, weights):
        lines.append("%3d  %7.3f  %7.3f  %12.4f" % (position, value, weight, contribution))
    lines.append("weighted average: %.4f" % weighted_average(values, weights))
    return "\n".join(lines)


def main():
    datasets = [
        ([10, 20, 30], [1, 2, 1]),
        ([5, 10], [0.5, 0.5]),
        ([88.5, 91.0, 79.25, 95.5], [0.2, 0.3, 0.1, 0.4]),
    ]
    for number in range(len(datasets)):
        (values, weights) = datasets[number]
        print("dataset %d" % (number + 1))
        print(format_report(values, weights))
        print()

    grades = {"math": (92.0, 4.0), "history": (81.0, 3.0), "art": (75.0, 1.0)}
    subjects = sorted(grades)
    scores = [grades[name][0] for name in subjects]
    credits = [grades[name][1] for name in subjects]
    gpa_shares = normalized_weights(credits)
    print("course summary")
    for rank in range(len(subjects)):
        print("%d. %-8s score=%5.1f credits=%.1f share=%.2f%%"
              % (rank + 1, subjects[rank], scores[rank], credits[rank], 100 * gpa_shares[rank]))
    print("overall: %.2f" % weighted_average(scores, credits))


if __name__ == "__main__":
    main()

