def generate_pin(length):
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(secrets.choice("0123456789") for _ in range(length))


def has_run(pin, run_length):
    streak = 1
    step = 0
    for position, digit in enumerate(pin):
        if position == 0:
            continue
        delta = int(digit) - int(pin[position - 1])
        if delta in (1, -1) and delta == step:
            streak += 1
        elif delta in (1, -1):
            streak = 2
            step = delta
        else:
            streak = 1
            step = 0
        if streak >= run_length:
            return True
    return False


def longest_repeat(pin):
    best = 1
    current = 1
    for position, digit in enumerate(pin):
        if position and digit == pin[position - 1]:
            current += 1
            if current > best:
                best = current
        else:
            current = 1
    return best


def grouped(pin, size=3):
    chunks = []
    for index, digit in enumerate(pin):
        if index and index % size == 0:
            chunks.append(" ")
        chunks.append(digit)
    return "".join(chunks)


def digit_counts(pin):
    counts = {}
    for digit in pin:
        counts[digit] = counts.get(digit, 0) + 1
    return counts


def weakness_report(pin):
    problems = []
    counts = digit_counts(pin)
    if len(counts) == 1:
        problems.append("all digits identical")
    if has_run(pin, 3):
        problems.append("contains an ascending or descending run")
    if longest_repeat(pin) >= 3:
        problems.append("three or more equal digits in a row")
    for digit, count in sorted(counts.items()):
        if count > max(2, len(pin) // 2):
            problems.append("digit %s repeats %d times" % (digit, count))
    return problems


def generate_strong_pin(length, attempts=50):
    for attempt in range(attempts):
        candidate = generate_pin(length)
        if not weakness_report(candidate):
            return candidate, attempt + 1
    return generate_pin(length), attempts


