    lines = []
    width = max(len(grouped(pin)) for pin in pins)
    for index, pin in enumerate(pins, start=1):
        notes = weakness_report(pin)
        summary = ", ".join(notes) if notes else "ok"
        lines.append("%2d. %-*s  %s" % (index, width, grouped(pin), summary))
    return lines


