def is_divisible_by_3_and_5(number):
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    return number % 3 == 0 and number % 5 == 0


def parse_numbers(tokens):
    numbers = []
    for position, token in enumerate(tokens):
        text = token.strip()
        try:
            numbers.append(int(text))
        except ValueError:
            raise ValueError("token %d is not an integer: %r" % (position, token))
    return numbers


def classify(numbers):
    results = []
    for index, number in enumerate(numbers):
        results.append((index, number, is_divisible_by_3_and_5(number)))
    return results


def missing_divisors(number):
    gaps = []
    for divisor in (3, 5):
        if number % divisor != 0:
            gaps.append(divisor)
    return gaps


def describe(number):
    if is_divisible_by_3_and_5(number):
        return "divisible by 3 and 5"
    gaps = missing_divisors(number)
    parts = []
    for rank, divisor in enumerate(gaps):
        prefix = "not divisible by " if rank == 0 else "nor by "
        parts.append(prefix + str(divisor))
    return " ".join(parts)


def format_report(results):
    lines = []
    width = len(str(max((len(results) - 1, 0))))
    for line_no, (index, number, is_divisible) in enumerate(results, start=1):
        lines.append(
            "%*d. n[%d] = %d -> %s (%s)"
            % (width + 1, line_no, index, number, is_divisible, describe(number))
        )
    return "\n".join(lines)


def summarize(results):
    hits = [number for _, number, flag in results if flag]
    ordinals = []
    for rank, number in enumerate(hits, start=1):
        ordinals.append("#%d:%d" % (rank, number))
    return "%d of %d divisible by 15 [%s]" % (
        len(hits),
        len(results),
        ", ".join(ordinals),
    )


def main(argv):
    tokens = argv[1:] or ["15", "10", "0", "-30", "7", "45"]
    numbers = parse_numbers(tokens)
    results = classify(numbers)
    print(format_report(results))
    print(summarize(results))


