def is_divisible_by_3_and_5(number):
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    return number % 3 == 0 and number % 5 == 0


def parse_numbers(tokens):
    numbers = []
    for position in range(len(tokens)):
        text = tokens[position].strip()
        try:
            numbers.append(int(text))
        except ValueError:
            raise ValueError("token %d is not an integer: %r" % (position, tokens[position]))
    return numbers


def classify(numbers):
    results = []
    for index in range(len(numbers)):
        results.append((index, numbers[index], is_divisible_by_3_and_5(numbers[index])))
    return results


def missing_divisors(number):
    gaps = []
    for divisor in (3, 5):
        if number % divisor != 0:
            gaps.append(divisor)
    return gaps


def describe(number):
    if is_divisible_by_3_and_5(number):
        return "divisible by 3 and 5"
    gaps = missing_divisors(number)
    parts = []
    for rank in range(len(gaps)):
        prefix = "not divisible by " if rank == 0 else "nor by "
        parts.append(prefix + str(gaps[rank]))
    return " ".join(parts)


def format_report(results):
    lines = []
    width = len(str(max((len(results) - 1, 0))))
    for line_no in range(len(results)):
        (index, number, is_divisible) = results[line_no]
        lines.append(
            "%*d. n[%d] = %d -> %s (%s)"
            % (width + 1, line_no + 1, index, number, is_divisible, describe(number))
        )
    return "\n".join(lines)


def summarize(results):
    hits = [number for _, number, flag in results if flag]
    ordinals = []
    for rank in range(len(hits)):
        ordinals.append("#%d:%d" % (rank + 1, hits[rank]))
    return "%d of %d divisible by 15 [%s]" % (
        len(hits),
        len(results),
        ", ".join(ordinals),
    )


def main(argv):
    tokens = argv[1:] or ["15", "10", "0", "-30", "7", "45"]
    numbers = parse_numbers(tokens)
    results = classify(numbers)
    print(format_report(results))
    print(summarize(results))


if __name__ == "__main__":
    import sys

    main(sys.argv)

