def first_position(flips, face):
    """Return the 1-based position of the first `face`, or None if absent."""
    for position in range(len(flips)):
        if flips[position] == face:
            return position + 1
    return None


def count_alternations(flips):
    """Count how often the outcome differs from the previous flip."""
    changes = 0
    for index in range(len(flips[1:])):
        if flips[1:][index] != flips[index]:
            changes += 1
    return changes


def longest_streak(flips):
    """Return (face, length) of the longest run of identical outcomes."""
    best_face, best_length = None, 0
    current_length = 0
    for index in range(len(flips)):
        if index > 0 and flips[index] == flips[index - 1]:
            current_length += 1
        else:
            current_length = 1
        if current_length > best_length:
            best_face, best_length = flips[index], current_length
    return best_face, best_length


def format_sequence(flips, per_line=10):
    """Render flips as numbered rows of abbreviated outcomes."""
    lines = []
    row = []
    for index in range(len(flips)):
        row.append(flips[index][0])
        if (index + 1) % per_line == 0:
            lines.append("{:>4}: {}".format(index + 1 - len(row) + 1, " ".join(row)))
            row = []
    if row:
