def minutes_to_hh_mm(total_minutes):
    if not isinstance(total_minutes, int) or isinstance(total_minutes, bool):
        raise TypeError("total_minutes must be an int")
    if total_minutes < 0:
        raise ValueError("total_minutes must not be negative")
    hours, minutes = divmod(total_minutes, 60)
    return "{:02d}:{:02d}".format(hours, minutes)


def parse_minutes(text):
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty value")
    for position, char in enumerate(cleaned):
        if char == "+" and position == 0:
            continue
        if not char.isdigit():
            raise ValueError("invalid character {!r} at position {}".format(char, position))
    return int(cleaned)


def parse_minutes_list(tokens):
    values = []
    for index, token in enumerate(tokens):
        try:
            values.append(parse_minutes(token))
        except ValueError as exc:
            raise ValueError("token #{} ({!r}): {}".format(index + 1, token, exc))
    return values


def cumulative_schedule(durations):
    rows = []
    elapsed = 0
    for leg, duration in enumerate(durations, start=1):
        elapsed += duration
        rows.append(("leg %d" % leg, minutes_to_hh_mm(duration), minutes_to_hh_mm(elapsed)))
    return rows


def column_widths(rows, headers):
    widths = list(len(header) for header in headers)
    for row in rows:
        for column, cell in enumerate(row):
            if len(cell) > widths[column]:
                widths[column] = len(cell)
    return widths


def format_table(rows, headers):
    widths = column_widths(rows, headers)
    lines = []
    header_cells = []
    for column, header in enumerate(headers):
        header_cells.append(header.ljust(widths[column]))
    lines.append(" | ".join(header_cells))
    lines.append("-+-".join("-" * width for width in widths))
    for number, row in enumerate(rows, start=1):
        cells = ["%2d" % number]
        for column, cell in enumerate(row):
            cells.append(cell.ljust(widths[column]))
        lines.append(" ".join(cells[:1]) + " " + " | ".join(cells[1:]))
    return lines


def main(argv):
    tokens = argv[1:] or ["70", "1440", "45", "605"]
    durations = parse_minutes_list(tokens)
    for index, duration in enumerate(durations):
        print("input[{}] = {} minutes -> {}".format(index, duration, minutes_to_hh_mm(duration)))
    print()
    schedule = cumulative_schedule(durations)
    for line in format_table(schedule, ["stage", "duration", "elapsed"]):
        print(line)
    print()
    print("total:", minutes_to_hh_mm(sum(durations)))


if __name__ == "__main__":
    import sys

    main(sys.argv)

