def validate_shapes(matrix1, matrix2):
    """Raise ValueError if the two matrices do not have identical shapes."""
    if len(matrix1) != len(matrix2):
        raise ValueError("row counts differ: %d vs %d" % (len(matrix1), len(matrix2)))
    for i, row1 in enumerate(matrix1):
        row2 = matrix2[i]
        if len(row1) != len(row2):
            raise ValueError("row %d has %d and %d columns" % (i, len(row1), len(row2)))


def matrix_subtract(matrix1, matrix2):
    """Return the element-wise difference matrix1 - matrix2."""
    validate_shapes(matrix1, matrix2)
    result_matrix = []
    for i, row1 in enumerate(matrix1):
        row2 = matrix2[i]
        diff_row = []
        for j, value in enumerate(row1):
            diff_row.append(value - row2[j])
        result_matrix.append(diff_row)
    return result_matrix


def column_widths(matrix):
    """Return the printing width needed by each column of the matrix."""
    widths = []
    for row in matrix:
        for j, value in enumerate(row):
            text_length = len(format_value(value))
            if j < len(widths):
                widths[j] = max(widths[j], text_length)
            else:
                widths.append(text_length)
    return widths


def format_value(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_matrix(matrix):
    """Render a matrix as aligned text lines, one line per row."""
    widths = column_widths(matrix)
    lines = []
    for row in matrix:
        cells = []
        for j, value in enumerate(row):
            cells.append(format_value(value).rjust(widths[j]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return lines


def report(matrix1, matrix2):
    """Print both operands and their difference side by side."""
    difference = matrix_subtract(matrix1, matrix2)
    blocks = [format_matrix(matrix1), format_matrix(matrix2), format_matrix(difference)]
    labels = ["minuend", "subtrahend", "difference"]
    for k, block in enumerate(blocks):
