def reverse_each_word(sentence):
    words = sentence.split(' ')
    reversed_words = []

    for i, word in enumerate(words):
        char_list = list(word)
        reversed_char_list = []

        for j, char in enumerate(reversed(char_list)):
            reversed_char_list.append(char)

        reversed_words.append("".join(reversed_char_list))

    final_reversed_words = []
    for k, r_word in enumerate(reversed_words):
        temp_chars = []
        for l, char_val in enumerate(r_word):
            temp_chars.append(char_val)
        final_reversed_words.append("".join(temp_chars))

    result_string_chars = []
    for m, final_word in enumerate(final_reversed_words):
        for n, char_s in enumerate(final_word):
            result_string_chars.append(char_s)
        if m < len(final_reversed_words) - 1:
