def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the profit (positive) or loss (negative) of one stock trade."""
    validate_trade(buy_price, sell_price, quantity)
    return (float(sell_price) - float(buy_price)) * quantity


def validate_trade(buy_price, sell_price, quantity):
    """Raise ValueError/TypeError if the trade values are not usable."""
    labels = ("buy_price", "sell_price")
    prices = (buy_price, sell_price)
    for index, value in enumerate(prices):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("%s must be numeric" % labels[index])
        if value < 0:
            raise ValueError("%s must not be negative" % labels[index])
    if not isinstance(quantity, int) or isinstance(quantity, bool):
        raise TypeError("quantity must be an integer")
    if quantity <= 0:
        raise ValueError("quantity must be positive")


def parse_trade_line(line):
    """Turn 'SYMBOL,buy,sell,qty' into (symbol, buy_price, sell_price, quantity)."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 4:
        raise ValueError("expected 4 fields, got %d" % len(fields))
    symbol = fields[0].upper()
    names = ("buy price", "sell price")
    raw_prices = fields[1:3]
    prices = []
    for index, raw in enumerate(raw_prices):
        if not raw:
            raise ValueError("missing %s for %s" % (names[index], symbol))
        prices.append(float(raw))
    return symbol, prices[0], prices[1], int(fields[3])


def column_widths(rows):
    """Return the widest cell length of every column of a table of strings."""
    if not rows:
        return []
    widths = [0] * len(rows[0])
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))
    return widths


def format_row(cells, widths):
    """Pad every cell to its column width and join the row."""
    parts = []
    for index, cell in enumerate(cells):
        parts.append(cell.ljust(widths[index]))
    return "  ".join(parts).rstrip()


def evaluate_portfolio(lines):
    """Compute the profit/loss of every trade line, keeping the input order."""
    results = []
    for index, line in enumerate(lines):
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        try:
            symbol, buy_price, sell_price, quantity = parse_trade_line(text)
            profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
        except (ValueError, TypeError) as error:
            results.append((index, text, None, str(error)))
            continue
        results.append((index, symbol, profit_loss, None))
    return results


def best_trade(results):
    """Return the position of the most profitable evaluated trade, if any."""
    best = None
    for index, item in enumerate(results):
        if item[2] is not None and (best is None or item[2] > results[best][2]):
            best = index
    return best


def format_report(results):
    """Build the printable lines of a portfolio report."""
    rows = [("line", "trade", "profit/loss")]
    for line_number, label, profit_loss, error in results:
        if error is None:
            rows.append((str(line_number), label, "%+.2f" % profit_loss))
        else:
            rows.append((str(line_number), label, "invalid: %s" % error))
    widths = column_widths(rows)
    report = [format_row(row, widths) for row in rows]
    report.append("Net profit/loss: %+.2f"
                  % sum(item[2] for item in results if item[2] is not None))
    best = best_trade(results)
    if best is not None:
        report.append("Best trade: %s (%+.2f)" % (results[best][1], results[best][2]))
    return report


def main():
    trade_lines = [
        "# symbol,buy,sell,quantity",
        "AAPL,10.0,12.0,100",
        "MSFT,15.0,13.0,50",
        "TSLA,240.5,255.25,12",
        "BAD,5.0,7.0,0",
        "SHORT,1.0,2.0",
    ]
    for text in format_report(evaluate_portfolio(trade_lines)):
        print(text)


if __name__ == "__main__":
    main()

