    decoded_parts = []
    current_number_str = ""

    for i, char in enumerate(encoded_string):
        if char.isdigit():
            current_number_str += char
        else:
            if current_number_str:
                count = int(current_number_str)
                decoded_parts.append(char * count)
                current_number_str = ""

    decoded_string_list = []
    for i, part in enumerate(decoded_parts):
        for j, char_in_part in enumerate(part):
            decoded_string_list.append(char_in_part)

    final_decoded_string = ""
    for i, char in enumerate(decoded_string_list):
        final_decoded_string += char

    intermediate_list = []
    for i, char_val in enumerate(final_decoded_string):
        intermediate_list.append(char_val)

    reconstructed_string = ""
    for i, item in enumerate(intermediate_list):
        reconstructed_string += item

    result_string_builder = []
