DIGITS = "0123456789ABCDEF"


def decimal_to_hex(decimal_num):
    if isinstance(decimal_num, bool) or not isinstance(decimal_num, int):
        raise TypeError("decimal_num must be an int")
    if decimal_num == 0:
        return "0"
    remaining = abs(decimal_num)
    digits = []
    while remaining:
        remaining, rem = divmod(remaining, 16)
        digits.append(DIGITS[rem])
    sign = "-" if decimal_num < 0 else ""
    return sign + "".join(reversed(digits))


def normalize_hex(hex_string):
    body = hex_string[1:] if hex_string.startswith("-") else hex_string
    if not body:
        raise ValueError("hex string has no digits")
    for pos, ch in enumerate(body):
        if ch.upper() not in DIGITS:
            raise ValueError("invalid hex digit %r at position %d" % (ch, pos))
    return body.upper()


def place_values(hex_string):
    body = normalize_hex(hex_string)
    terms = []
    for index, ch in enumerate(body):
        power = len(body) - 1 - index
        terms.append((ch, power, DIGITS.index(ch) * 16 ** power))
    return terms


def hex_to_decimal(hex_string):
    total = sum(term[2] for term in place_values(hex_string))
    return -total if hex_string.startswith("-") else total


def explain(hex_string):
    pieces = ["%s*16^%d(%d)" % term for term in place_values(hex_string)]
    return "%s = %s = %d" % (hex_string, " + ".join(pieces), hex_to_decimal(hex_string))


def render_table(headers, rows):
    widths = [len(h) for h in headers]
    for row in rows:
        for col, cell in enumerate(row):
            if len(cell) > widths[col]:
                widths[col] = len(cell)
    lines = [" | ".join(h.ljust(widths[i]) for i, h in enumerate(headers))]
    lines.append("-+-".join("-" * w for w in widths))
    for row in rows:
        lines.append(" | ".join(c.ljust(widths[j]) for j, c in enumerate(row)))
    return "\n".join(lines)


def main():
    samples = [0, 10, 255, 4095, 65535, -48]
    rows = []
    for index, value in enumerate(samples):
        hex_string = decimal_to_hex(value)
        rows.append([str(index), str(value), hex_string, str(hex_to_decimal(hex_string))])
    print(render_table(["row", "decimal", "hex", "round-trip"], rows))
    print()
    for value in samples:
        if value > 0:
            print(explain(decimal_to_hex(value)))


if __name__ == "__main__":
    main()

