HEX_DIGITS = "0123456789ABCDEF"


def digit_value(char):
    """Return the numeric value of a single hexadecimal digit."""
    upper = char.upper()
    for value in range(len(HEX_DIGITS)):
        if HEX_DIGITS[value] == upper:
            return value
    raise ValueError("invalid hexadecimal digit: %r" % char)


def normalize(hex_string):
    """Strip whitespace, an optional sign and an optional 0x prefix."""
    text = hex_string.strip()
    sign = 1
    if text[:1] in ("+", "-"):
        if text[0] == "-":
            sign = -1
        text = text[1:]
    if text[:2].lower() == "0x":
        text = text[2:]
    if not text:
        raise ValueError("no hexadecimal digits found in %r" % hex_string)
    return sign, text.upper()


def validate(digits):
    """Raise a ValueError naming the position of the first bad character."""
    for position in range(len(digits)):
        if digits[position] not in HEX_DIGITS:
            raise ValueError("bad character %r at position %d" % (digits[position], position))


def hex_to_decimal(hex_string):
    """Convert a hexadecimal string to its decimal integer representation."""
    sign, digits = normalize(hex_string)
    validate(digits)
    decimal_num = 0
    for index in range(len(digits)):
        exponent = len(digits) - 1 - index
        decimal_num += digit_value(digits[index]) * (16 ** exponent)
    return sign * decimal_num


def breakdown(hex_string):
    """Describe each digit's contribution, most significant first."""
    _, digits = normalize(hex_string)
    validate(digits)
    terms = []
    for index in range(len(digits)):
        exponent = len(digits) - 1 - index
        terms.append("%s*16^%d=%d" % (digits[index], exponent, digit_value(digits[index]) * 16 ** exponent))
    return terms


def format_report(samples):
    """Build numbered report lines for a sequence of hexadecimal strings."""
    width = max(len(sample) for sample in samples)
    lines = []
    for index in range(len(samples)):
        value = hex_to_decimal(samples[index])
        detail = " + ".join(breakdown(samples[index]))
        lines.append("%2d. %-*s = %-12d [%s]" % (index + 1, width, samples[index], value, detail))
    return lines


def main():
    samples = ["FF", "A", "0x1f4", "  deadBEEF ", "-2A", "000", "7fffffff"]
    for line in format_report(samples):
        print(line)
