    lines = []
    width = max((len(k) for k in summary), default=0)
    ranked = sorted(summary.items(), key=lambda kv: (-kv[1], kv[0]))
    for rank, (keyword, count) in enumerate(ranked, start=1):
        lines.append("%2d. %-*s %d" % (rank, width, keyword, count))
    return "\n".join(lines)


