MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
FIELD_SPECS = (('year', 4), ('month', 2), ('day', 2))
ALIGNMENTS = ('left', 'left', 'right')


def column_widths(rows):
    widths = []
    for row in rows:
        for index, cell in enumerate(row):
            if index == len(widths):
                widths.append(len(cell))
            elif len(cell) > widths[index]:
                widths[index] = len(cell)
    return widths


def format_row(row, widths):
    cells = []
    for index, cell in enumerate(row):
        if ALIGNMENTS[index] == 'right':
            cells.append(cell.rjust(widths[index]))
        else:
            cells.append(cell.ljust(widths[index]))
    return '  '.join(cells)


def render_table(rows):
    widths = column_widths(rows)
    lines = []
    for index, row in enumerate(rows):
        lines.append(format_row(row, widths))
        if index == 0:
            lines.append('-' * len(lines[0]))
    return lines


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("expected 'YYYY-MM-DD', got %r" % date_str)
    values = []
    for index, spec in enumerate(FIELD_SPECS):
        name, width = spec
        chunk = parts[index]
        if len(chunk) != width or not chunk.isdigit():
            raise ValueError('invalid %s field %r in %r' % (name, chunk, date_str))
        values.append(int(chunk))
    year, month, day = values
    if not 1 <= month <= 12:
        raise ValueError('month out of range in %r' % date_str)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError('day out of range in %r' % date_str)
    return year, month, day


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def days_before_month(year, month):
    total = 0
    for index, length in enumerate(MONTH_LENGTHS):
        if index >= month - 1:
            break
        total += length
        if index == 1 and is_leap(year):
            total += 1
    return total


def to_ordinal(year, month, day):
    previous = year - 1
    leaps = previous // 4 - previous // 100 + previous // 400
    return 365 * previous + leaps + days_before_month(year, month) + day


def days_between_dates(start_date_str, end_date_str):
    start, end = parse_date(start_date_str), parse_date(end_date_str)
    return to_ordinal(*end) - to_ordinal(*start)


def build_report(cases):
    rows = [('start', 'end', 'days')]
    for start, end in cases:
        rows.append((start, end, '%+d' % days_between_dates(start, end)))
    return rows


def main():
    cases = [('2023-01-01', '2023-01-05'), ('2023-01-01', '2022-12-25'),
             ('2020-02-28', '2020-03-01'), ('1999-12-31', '2000-01-01')]
    for line in render_table(build_report(cases)):
        print(line)


if __name__ == '__main__':
    main()

