    points = [(3, 3), (6, 2), (0, 0), (5, 1), (2, 7), (4, 4)]

    print(f"rectangle: bottom-left {rect[0], rect[1]} top-right {rect[2], rect[3]}")
    print(format_table(points, rect))
    print(render_grid(points, rect, 8, 8))

    inside = indices_inside(points, rect)
    print(f"contained points: {[points[i] for i in inside]}")
    missing = first_outside_index(points, rect)
    if missing >= 0:
        print(f"first point outside: index {missing} -> {points[missing]}")

    for index, (px, py) in enumerate(points):
        verdict = is_point_in_rectangle(px, py, *rect)
        print(f"is_point_in_rectangle({px}, {py}, {', '.join(str(c) for c in rect)}) = {verdict} [{index}]")


if __name__ == "__main__":
    main()

