def calculate_simple_interest(principal, rate, time):
    """Return the simple interest earned on `principal` at `rate`% for `time` years."""
    validate_inputs(principal, rate, time)
    return principal * rate * time / 100.0


def validate_inputs(principal, rate, time):
    """Reject non-numeric or negative loan parameters before any arithmetic."""
    labels = ("principal", "rate", "time")
    values = (principal, rate, time)
    for index in range(len(values)):
        if isinstance(values[index], bool) or not isinstance(values[index], (int, float)):
            raise TypeError("%s must be a number, got %r" % (labels[index], values[index]))
        if values[index] < 0:
            raise ValueError("%s must not be negative, got %r" % (labels[index], values[index]))
    if int(time) != time:
        raise ValueError("time must be a whole number of years, got %r" % (time,))


def parse_offers(specs):
    """Turn "rate:years" strings into (rate, time) pairs."""
    offers = []
    for position in range(len(specs)):
        fields = specs[position].split(":")
        if len(fields) != 2:
            raise ValueError("offer %d must look like RATE:YEARS, got %r" % (position, specs[position]))
        try:
            rate, time = float(fields[0]), int(fields[1])
        except ValueError:
            raise ValueError("offer %d has non-numeric parts: %r" % (position, specs[position]))
        offers.append((rate, time))
    return offers


