def _validate(name, value):
    if not isinstance(value, list):
        raise TypeError("%s must be a list, got %s" % (name, type(value).__name__))
    for index, item in enumerate(value):
        try:
            hash(item)
        except TypeError:
            raise TypeError("%s[%d] is unhashable: %r" % (name, index, item))


def _first_positions(items):
    """Map each distinct element to the index where it first appears."""
    positions = {}
    for index, item in enumerate(items):
        if item not in positions:
            positions[item] = index
    return positions


def find_common_elements(list1, list2):
    """Return the elements that appear in both lists, without duplicates."""
    _validate("list1", list1)
    _validate("list2", list2)
    second = set(list2)
    seen = set()
    common = []
    for item in list1:
        if item in second and item not in seen:
            seen.add(item)
            common.append(item)
    return common


def describe_matches(list1, list2):
    """Pair every common element with its first index in each input list."""
    left = _first_positions(list1)
    right = _first_positions(list2)
    return [(item, left[item], right[item]) for item in find_common_elements(list1, list2)]


def format_report(list1, list2):
    lines = ["list1 = %r" % (list1,), "list2 = %r" % (list2,)]
    matches = describe_matches(list1, list2)
    if not matches:
        lines.append("no common elements")
        return lines
    for rank, (item, i, j) in enumerate(matches, start=1):
        lines.append("%d. %r at list1[%d] and list2[%d]" % (rank, item, i, j))
    lines.append("common = %r" % (find_common_elements(list1, list2),))
    return lines


def main():
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        (['x', 'y', 'x', 'z'], ['z', 'x', 'w']),
        ([], [1, 2]),
    ]
