def parse_digits(card_number):
    if not isinstance(card_number, str):
        raise TypeError("card_number must be a string")
    digits = []
    for position, char in enumerate(card_number):
        if not char.isdigit():
            raise ValueError("non-digit %r at position %d" % (char, position))
        digits.append(int(char))
    if not digits:
        raise ValueError("card_number must contain at least one digit")
    return digits


def doubled_digits(digits):
    weighted = []
    for index, digit in enumerate(digits):
        if (len(digits) - index) % 2 == 0:
            product = digit * 2
            weighted.append(product - 9 if product > 9 else product)
        else:
            weighted.append(digit)
    return weighted


def luhn_sum(card_number):
    return sum(doubled_digits(parse_digits(card_number)))


def is_valid_luhn(card_number):
    return luhn_sum(card_number) % 10 == 0


