def validate_input(input_dict, threshold):
    """Check the arguments and raise a descriptive error for bad data."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be an int or a float")
    for position, (key, value) in enumerate(input_dict.items()):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                "entry %d (key %r) has non-numeric value %r" % (position, key, value)
            )
    return True


def parse_pairs(text):
    """Read 'key=value' lines into a dictionary of numbers."""
    parsed = {}
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        if "=" not in stripped:
            raise ValueError("line %d: expected 'key=value', got %r" % (lineno, stripped))
        key, raw = stripped.split("=", 1)
        try:
            parsed[key.strip()] = float(raw)
        except ValueError:
            raise ValueError("line %d: %r is not a number" % (lineno, raw.strip()))
    return parsed


def filter_dict_by_value(input_dict, threshold):
    """Return the pairs of input_dict whose value is greater than threshold."""
    validate_input(input_dict, threshold)
    return {key: value for key, value in input_dict.items() if value > threshold}


def rank_entries(filtered):
    """Order the surviving pairs from the largest value down and number them."""
    ordered = sorted(filtered.items(), key=lambda pair: (-pair[1], pair[0]))
    return [(rank, key, value) for rank, (key, value) in enumerate(ordered, start=1)]


def format_report(input_dict, threshold):
    """Build a human readable report about one filtering run."""
    filtered = filter_dict_by_value(input_dict, threshold)
    lines = ["threshold %g kept %d of %d entries" % (threshold, len(filtered), len(input_dict))]
    if not filtered:
        lines.append("  (nothing above the threshold)")
    for rank, key, value in rank_entries(filtered):
        lines.append("  %d. %s = %g" % (rank, key, value))
    return "\n".join(lines)


def format_sweep(input_dict, thresholds):
    """Filter the same dictionary with several thresholds, one line per step."""
    lines = []
    for step, threshold in enumerate(thresholds, start=1):
        filtered = filter_dict_by_value(input_dict, threshold)
        keys = ", ".join(sorted(filtered)) if filtered else "-"
        lines.append("step %d (> %g): %s" % (step, threshold, keys))
    return "\n".join(lines)


def main():
    cases = [
        ({'a': 10, 'b': 20, 'c': 5}, 15),
        ({'x': 1, 'y': 2}, 5),
        ({'temp': 21.5, 'humidity': 48.0, 'pressure': 1013.0}, 50),
    ]
    for number, (data, threshold) in enumerate(cases, start=1):
        print("case %d: %r" % (number, data))
        print("  result: %r" % (filter_dict_by_value(data, threshold),))
        for line in format_report(data, threshold).splitlines():
            print("  " + line)

    scores = parse_pairs("ana=72\nbo=55\ncy=91\ndee=68\n")
    print("sweep over %r" % (scores,))
    print(format_sweep(scores, [50, 70, 90, 95]))

    try:
        filter_dict_by_value({'ok': 1, 'bad': 'two'}, 0)
    except TypeError as error:
        print("rejected: %s" % error)


if __name__ == "__main__":
    main()

