def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9.0 / 5.0 + 32.0


def parse_readings(text):
    """Parse whitespace/comma separated Celsius readings, reporting bad tokens."""
    readings = []
    tokens = text.replace(",", " ").split()
    for position, token in enumerate(tokens, start=1):
        try:
            readings.append(float(token))
        except ValueError:
            raise ValueError("reading #%d is not a number: %r" % (position, token))
    return readings


def convert_all(celsius_values):
    """Convert a sequence of Celsius values to Fahrenheit."""
    return [celsius_to_fahrenheit(value) for value in celsius_values]


def format_table(celsius_values):
    """Build aligned table lines for the given Celsius values."""
    lines = ["  #   Celsius   Fahrenheit", "---  --------  -----------"]
    for index, celsius in enumerate(celsius_values, start=1):
        fahrenheit = celsius_to_fahrenheit(celsius)
        lines.append("%3d  %8.2f  %11.2f" % (index, celsius, fahrenheit))
    return lines


def summarize(celsius_values):
    """Return the coldest and hottest reading together with their positions."""
    coldest_index = 0
    hottest_index = 0
    for index, celsius in enumerate(celsius_values):
        if celsius < celsius_values[coldest_index]:
            coldest_index = index
        if celsius > celsius_values[hottest_index]:
            hottest_index = index
    return {
        "coldest": (coldest_index + 1, celsius_values[coldest_index]),
        "hottest": (hottest_index + 1, celsius_values[hottest_index]),
    }


def freezing_positions(celsius_values):
    """Positions (1-based) of readings at or below the freezing point."""
    positions = []
    for index, celsius in enumerate(celsius_values, start=1):
        if celsius <= 0.0:
            positions.append(index)
    return positions


def main(argv=None):
    import sys

    argv = sys.argv[1:] if argv is None else argv
    source = " ".join(argv) if argv else "0 100 -40 21.5 37 -273.15"
    celsius_values = parse_readings(source)

    for line in format_table(celsius_values):
        print(line)

    stats = summarize(celsius_values)
    for label, (position, celsius) in stats.items():
        print("%s: reading #%d at %.2f C = %.2f F"
              % (label, position, celsius, celsius_to_fahrenheit(celsius)))

    frozen = freezing_positions(celsius_values)
    if frozen:
        print("at or below freezing: " + ", ".join("#%d" % p for p in frozen))

    fahrenheit_values = convert_all(celsius_values)
    for index, fahrenheit in enumerate(fahrenheit_values, start=1):
        if fahrenheit < -459.67:
            print("warning: reading #%d is below absolute zero" % index)


if __name__ == "__main__":
    main()

