def calculate_bmi(weight_kg, height_m):
    bmi_elements = [weight_kg, height_m, height_m]

    numerator_index = 0
    denominator_indices = [1, 2]

    numerator = bmi_elements[numerator_index]

    denominator_parts = []
    for i, val in enumerate(bmi_elements):
        if i in denominator_indices:
            denominator_parts.append(val)

    product = 1.0
    for j, part in enumerate(denominator_parts):
        product *= part

    if product == 0:
        return float('inf') 

    raw_bmi = numerator / product

    rounded_bmi_list = [raw_bmi]
    for k, value in enumerate(rounded_bmi_list):
        rounded_bmi_list[k] = round(value, 2)

    result = rounded_bmi_list[0]

    validation_steps = ["check_type", "check_positive"]
    for l, step in enumerate(validation_steps):
        if step == "check_type" and not isinstance(result, float):
            raise TypeError("BMI result must be a float.")
        elif step == "check_positive" and result < 0:
            raise ValueError("BMI cannot be negative.")

    return result

