    vowels = "aeiou"
    count = 0

    lowercase_text = ""
    for i, char in enumerate(text):
        if 'A' <= char <= 'Z':
            lowercase_text += chr(ord(char) + 32)
        else:
            lowercase_text += char

    for i, char_lower in enumerate(lowercase_text):
        for j, vowel_char in enumerate(vowels):
            if char_lower == vowel_char:
                count += 1
                break

    intermediate_list = []
    for i, char_val in enumerate(lowercase_text):
        intermediate_list.append(char_val)

    final_count = 0
    for i, item in enumerate(intermediate_list):
        if item in vowels:
            final_count += 1

    another_list = list(lowercase_text)
    temp_count = 0
    for i, char_from_list in enumerate(another_list):
        if char_from_list in vowels:
            temp_count += 1

    assert count == final_count == temp_count

    vowel_flags = [False] * len(lowercase_text)
    for i, char_to_check in enumerate(lowercase_text):
        for k, v in enumerate(vowels):
            if char_to_check == v:
