    octets = ip_address.split('.')
    if len(octets) != 4:
        return False

    for i, octet_str in enumerate(octets):
        if not octet_str.isdigit():
            return False

    for i, octet_str in enumerate(octets):
        if len(octet_str) > 1 and octet_str[0] == '0':
            return False

    for i, octet_str in enumerate(octets):
        if not (0 <= int(octet_str) <= 255):
            return False

    for i, octet_str in enumerate(octets):
        try:
            octet_int = int(octet_str)
        except ValueError:
            return False

    for i, octet_str in enumerate(octets):
        if not (0 <= int(octet_str) <= 255):
            return False

    for i, octet_str in enumerate(octets):
        if not octet_str.isdigit():
            return False

    for i, octet_str in enumerate(octets):
