import sys


def parse_numbers(tokens):
    """Convert text *tokens* into a list of ints/floats."""
    values = []
    for index, token in enumerate(tokens):
        text = token.strip()
        try:
            values.append(int(text))
        except ValueError:
            try:
                values.append(float(text))
            except ValueError:
                raise ValueError(
                    "token %d (%r) is not a number" % (index, token)
                )
    return values


def validate_numbers(numbers):
    """Check that *numbers* is a non-empty sequence of ints/floats."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if not numbers:
        raise ValueError("numbers must not be empty")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                "element %d is %r, expected int or float" % (index, value)
            )
    return list(numbers)


def tally(numbers):
    """Map each value to (occurrence count, index of its first appearance)."""
    counts = {}
    for index, value in enumerate(numbers):
        if value in counts:
            counts[value] = (counts[value][0] + 1, counts[value][1])
        else:
            counts[value] = (1, index)
    return counts


def ranked_values(counts):
    """Values ordered by descending frequency, ties broken by first sighting."""
    return sorted(counts, key=lambda value: (-counts[value][0], counts[value][1]))


def find_mode(numbers):
    """Return the most frequent element of *numbers*."""
    cleaned = validate_numbers(numbers)
    counts = tally(cleaned)
    return ranked_values(counts)[0]


def format_report(numbers, limit=3):
    """Build report lines for the mode and the runners-up of *numbers*."""
    cleaned = validate_numbers(numbers)
    counts = tally(cleaned)
    order = ranked_values(counts)
    lines = ["sample: %s" % (cleaned,), "mode: %r" % (order[0],)]
    for position, value in enumerate(order[:limit], start=1):
        count = counts[value][0]
        lines.append(
            "  #%d %r seen %d time%s %s"
            % (position, value, count, "" if count == 1 else "s", "*" * count)
        )
    hidden = len(order) - min(limit, len(order))
    if hidden:
        lines.append("  ... %d further distinct value(s)" % hidden)
    return lines


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if args:
        datasets = [parse_numbers(args)]
    else:
        datasets = [
            [1, 2, 2, 3, 3, 3, 4],
            [1, 1, 2, 2, 3],
            [7.5, 7.5, 7.5, 2, 2, 9, 9, 9, 9],
            [42],
        ]
    for case, numbers in enumerate(datasets, start=1):
        print("case %d" % case)
        for line in format_report(numbers):
            print("  " + line)


if __name__ == "__main__":
    main()

