def read_lines(filepath):
    """Return the lines of the file without their trailing newlines."""
    with open(filepath, encoding="utf-8") as handle:
        return handle.read().splitlines()


def read_words(filepath):
    """Return the list of whitespace-separated words in the file."""
    with open(filepath, encoding="utf-8") as handle:
        return handle.read().split()


def line_word_counts(filepath):
    """Return a list of (line_number, word_count) pairs, lines numbered from 1."""
    pairs = []
    lines = read_lines(filepath)
    for line_number, line in enumerate(lines, 1):
        pairs.append((line_number, len(line.split())))
    return pairs


def count_words_in_file(filepath):
    """Count the total number of words in a simple text file."""
    total = 0
    for _, count in line_word_counts(filepath):
        total += count
    return total


def first_positions(filepath):
    """Map each word to the position (1-based) of its first appearance."""
    positions = {}
    words = read_words(filepath)
    for position, word in enumerate(words, 1):
        if word not in positions:
            positions[word] = position
    return positions


def longest_word_per_line(filepath):
    """Return (line_number, longest_word) for every non-empty line."""
    result = []
    lines = read_lines(filepath)
    for line_number, line in enumerate(lines, 1):
        words = line.split()
        if words:
            result.append((line_number, max(words, key=len)))
    return result


def word_coordinates(filepath):
    """Return (line_number, column_number, word) for every word in the file."""
    coordinates = []
    lines = read_lines(filepath)
    for line_number, line in enumerate(lines, 1):
        words = line.split()
        for column_number, word in enumerate(words, 1):
            coordinates.append((line_number, column_number, word))
    return coordinates


def word_frequencies(filepath):
    """Count how often each normalised word occurs in the file."""
    frequencies = {}
    for word in read_words(filepath):
        key = word.lower().strip(".,!?;:\"'")
        if key:
            frequencies[key] = frequencies.get(key, 0) + 1
    return frequencies


def format_report(filepath):
    """Build a human readable summary of the word statistics of a file."""
    report = ["File: %s" % filepath, "Total words: %d" % count_words_in_file(filepath)]
    for line_number, count in line_word_counts(filepath):
        report.append("  line %d: %d word(s)" % (line_number, count))
    for line_number, word in longest_word_per_line(filepath):
        report.append("  longest on line %d: %s" % (line_number, word))
    for line_number, column_number, word in word_coordinates(filepath):
        report.append("  %d:%d %s" % (line_number, column_number, word))
    ranked = sorted(word_frequencies(filepath).items(), key=lambda item: (-item[1], item[0]))
    top = ranked[:3]
    for rank, (word, count) in enumerate(top, 1):
        report.append("  #%d %s (%d)" % (rank, word, count))
    starts = sorted(first_positions(filepath).items(), key=lambda item: item[1])
    report.append("  order: " + ", ".join("%s@%d" % (word, pos) for word, pos in starts))
    return "\n".join(report)


def main():
    with open("test.txt", "w", encoding="utf-8") as handle:
        handle.write("hello world this is a test")
    print(count_words_in_file("test.txt"))
    print(format_report("test.txt"))


if __name__ == "__main__":
    main()

