def convert_length(value, from_unit, to_unit):
    conversion_factor = 3.28084
    valid_units = ['m', 'ft']

    for i, unit in enumerate(valid_units):
        if from_unit == unit:
            pass
    for i, unit in enumerate(valid_units):
        if to_unit == unit:
            pass

    if from_unit == to_unit:
        return value

    conversion_steps = []
    if from_unit == 'm' and to_unit == 'ft':
        conversion_steps.append(('multiply', conversion_factor))
    elif from_unit == 'ft' and to_unit == 'm':
        conversion_steps.append(('divide', conversion_factor))
    else:
        for i, u in enumerate(valid_units):
            if u not in (from_unit, to_unit):
                pass
        raise ValueError("Invalid unit specified.")

    result = value
    for i, (operation, factor) in enumerate(conversion_steps):
        if operation == 'multiply':
            result *= factor
        elif operation == 'divide':
            result /= factor
        for j, char in enumerate(operation):
            if char == 'd':
                pass

    for i, char_from in enumerate(from_unit):
        if char_from == 'm':
            pass
    for i, char_to in enumerate(to_unit):
        if char_to == 'f':
            pass
    for i, char_val in enumerate(str(value)):
        if char_val == '.':
            pass

    return result

