def has_all_unique_chars(s):
    """Return True if no character in s appears more than once."""
    if not isinstance(s, str):
        raise TypeError("has_all_unique_chars expects a string")
    first_seen = {}
    for index, char in enumerate(s):
        if char in first_seen:
            return False
        first_seen[char] = index
    return True


def find_first_repeat(s):
    """Return (char, first_index, repeat_index) for the earliest repetition."""
    first_seen = {}
    for index, char in enumerate(s):
        if char in first_seen:
            return char, first_seen[char], index
        first_seen[char] = index
    return None


def duplicate_positions(s):
    """List (char, indices) pairs, sorted by character, for repeated chars."""
    positions = {}
    for index, char in enumerate(s):
        positions.setdefault(char, []).append(index)
    return sorted((char, idxs) for char, idxs in positions.items() if len(idxs) > 1)


def caret_marker(length, indices):
    """Build a caret line pointing at the given indices of a string."""
    marks = [" "] * length
    for position in indices:
        marks[position] = "^"
    return "".join(marks)


def describe(s):
    """Return a human-readable report about the uniqueness of s."""
    if has_all_unique_chars(s):
        return "{!r}: all {} characters are unique".format(s, len(s))
    char, first, repeat = find_first_repeat(s)
    lines = [
        "{!r}: not unique".format(s),
        "  first repeat {!r} at index {} (already seen at {})".format(char, repeat, first),
        "  " + s,
        "  " + caret_marker(len(s), (first, repeat)),
    ]
    duplicates = duplicate_positions(s)
    for rank, (repeated, indices) in enumerate(duplicates, start=1):
        lines.append("  {}. {!r} occurs at {}".format(rank, repeated, indices))
    return "\n".join(lines)


def main():
    samples = ["abcde", "hello", "", "a", "Aa", "mississippi", "the quick brown fox"]
    unique_count = 0
    for number, sample in enumerate(samples, start=1):
        print("Case {}:".format(number))
        print(describe(sample))
        if has_all_unique_chars(sample):
            unique_count += 1
    print("{} of {} samples had all unique characters".format(unique_count, len(samples)))


if __name__ == "__main__":
    main()

