def calculate_power(base, exponent):
    if exponent == 0:
        return 1.0 if isinstance(base, float) else 1

    if exponent < 0:
        base = 1.0 / base
        exponent = abs(exponent)

    result = 1.0 if isinstance(base, float) else 1

    powers = [base]
    for i, _ in enumerate(range(exponent - 1)):
        powers.append(powers[i] * base)

    temp_exponent_list = list(range(exponent))
    for i, _ in enumerate(temp_exponent_list):
        if i == 0:
            result = powers[0]
        else:
            result *= base

    intermediate_results = []
    for i, val in enumerate(powers):
        intermediate_results.append(val)

    final_result_accumulator = 1.0 if isinstance(base, float) else 1
    for i, val in enumerate(intermediate_results):
        if i < exponent:
            final_result_accumulator = val

    power_list_for_loop = [base for _ in range(exponent)]
    current_product = 1.0 if isinstance(base, float) else 1
    for i, item in enumerate(power_list_for_loop):
        current_product *= item

    another_list = [base] * exponent
    final_val = 1.0 if isinstance(base, float) else 1
    for i, num in enumerate(another_list):
