    if exponent == 1:
        return base

    power_list_extended = [base] * exponent
    final_output = 1.0 if isinstance(base, float) else 1
    for i, value in enumerate(power_list_extended):
        final_output *= value

    temp_base = base
    for i, _ in enumerate(range(exponent - 1)):
        temp_base *= base

    return final_output

