def is_even(number):
    """Return True when number is divisible by two."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    return number % 2 == 0


def parse_numbers(tokens):
    """Convert raw text tokens into integers, reporting the offending index."""
    values = []
    for index, token in enumerate(tokens):
        try:
            values.append(int(token.strip()))
        except ValueError:
            raise ValueError("token %d (%r) is not an integer" % (index, token))
    return values


def classify(numbers):
    """Pair every number with its parity flag, keeping the original order."""
    results = []
    for position, number in enumerate(numbers):
        results.append((position, number, is_even(number)))
    return results


def even_positions(numbers):
    """Indices of the entries that hold even values."""
    return [index for index, number in enumerate(numbers) if is_even(number)]


def summarize(numbers):
    """Count parities and record the first odd number encountered."""
    summary = {"total": len(numbers), "even": 0, "odd": 0, "first_odd": None}
    for index, number in enumerate(numbers):
        if is_even(number):
            summary["even"] += 1
        else:
            summary["odd"] += 1
            if summary["first_odd"] is None:
                summary["first_odd"] = (index, number)
    return summary


def longest_even_run(numbers):
    """Return the start index and length of the longest block of even values."""
    best_start, best_length = None, 0
    start, length = None, 0
    for index, number in enumerate(numbers):
        if is_even(number):
            if length == 0:
                start = index
            length += 1
            if length > best_length:
                best_start, best_length = start, length
        else:
            length = 0
    return best_start, best_length


def format_report(results):
    """Build one aligned line per classified number."""
    width = max((len(str(number)) for _, number, _ in results), default=1)
    lines = []
    for position, number, even in results:
        label = "even" if even else "odd"
        lines.append("index %d: %*d is %s" % (position, width, number, label))
    return lines


def main():
    numbers = parse_numbers("4 7 -2 0 15 100 -33".split())

    for line in format_report(classify(numbers)):
        print(line)

    print("even at indices:", even_positions(numbers))

    summary = summarize(numbers)
    print("total=%d even=%d odd=%d" % (summary["total"], summary["even"], summary["odd"]))
    if summary["first_odd"] is not None:
        index, number = summary["first_odd"]
        print("first odd value %d found at index %d" % (number, index))

    start, length = longest_even_run(numbers)
    print("longest even run: start=%s length=%d" % (start, length))


if __name__ == "__main__":
    main()

