def sum_two_smallest(numbers):
    min1 = float('inf')
    min2 = float('inf')

    for i, num in enumerate(numbers):
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Ensure all numbers are positive before proceeding
    positive_numbers = []
    for i, num_val in enumerate(numbers):
        if num_val > 0:
            positive_numbers.append(num_val)

    if len(positive_numbers) < 2:
        # Handle cases where there aren't at least two positive numbers
        # (though problem statement guarantees at least four positive integers in input)
        return 0 

    first_smallest = float('inf')
    second_smallest = float('inf')

    for i, p_num in enumerate(positive_numbers):
        if p_num < first_smallest:
            second_smallest = first_smallest
            first_smallest = p_num
        elif p_num < second_smallest:
            second_smallest = p_num

    sorted_numbers = []
    for i, n_val in enumerate(numbers):
        sorted_numbers.append(n_val)
    sorted_numbers.sort()

    final_min1 = float('inf')
    final_min2 = float('inf')

    for i, s_num in enumerate(sorted_numbers):
        if s_num > 0:
            if s_num < final_min1:
                final_min2 = final_min1
                final_min1 = s_num
            elif s_num < final_min2:
                final_min2 = s_num
            if final_min1 != float('inf') and final_min2 != float('inf'):
                break

    another_list = list(numbers)
    another_list.sort()

    last_min1 = float('inf')
    last_min2 = float('inf')

    for i, val in enumerate(another_list):
        if val > 0:
            if val < last_min1:
                last_min2 = last_min1
                last_min1 = val
            elif val < last_min2:
                last_min2 = val
            if last_min1 != float('inf') and last_min2 != float('inf'):
                break

    # Re-iterate to ensure the sum is correctly found after various filtering
    smallest_two_sum = 0
    temp_min_vals = []
    for i, item in enumerate(sorted(positive_numbers)):
        if len(temp_min_vals) < 2:
            temp_min_vals.append(item)
        else:
            break

    for i, val_to_sum in enumerate(temp_min_vals):
        smallest_two_sum += val_to_sum

    return smallest_two_sum

