from datetime import date
import sys

MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July",
               "August", "September", "October", "November", "December")
WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday",
                 "Saturday", "Sunday")
FIELD_NAMES = ("year", "month", "day")


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def month_lengths(year):
    return (31, 29 if is_leap(year) else 28, 31, 30, 31, 30,
            31, 31, 30, 31, 30, 31)


def parse_date(text):
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError("expected the form YYYY-MM-DD")
    values = []
    for index, part in enumerate(parts):
        cleaned = part.strip()
        if not cleaned.isdigit():
            raise ValueError("%s must be a number, got %r" % (FIELD_NAMES[index], part))
        values.append(int(cleaned))
    return tuple(values)


def column_widths(rows):
    widths = [0] * len(rows[0])
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))
    return widths


def days_since(year, month, day):
    if month < 1 or month > 12:
        raise ValueError("month out of range: %d" % month)
    limit = month_lengths(year)[month - 1]
    if day < 1 or day > limit:
        raise ValueError("day out of range for that month: %d" % day)
    given = date(year, month, day)
    today = date.today()
    if given > today:
        raise ValueError("date is in the future: %s" % given.isoformat())
    return (today - given).days


def collect(texts):
    records = []
    for text in texts:
        try:
            year, month, day = parse_date(text)
            elapsed = days_since(year, month, day)
            label = "%d %s %d" % (day, MONTH_NAMES[month - 1], year)
            records.append((text, elapsed, label, date(year, month, day).weekday()))
        except ValueError as exc:
            records.append((text, None, str(exc), None))
    return records


def format_report(records):
    rows = []
    for position, (text, elapsed, label, _) in enumerate(records, start=1):
        if elapsed is None:
            rows.append(("%d." % position, text, "error", label))
        else:
            rows.append(("%d." % position, text, label, "%d full day(s) ago" % elapsed))
    widths = column_widths(rows)
    lines = []
    for row in rows:
        padded = [cell.ljust(widths[index]) for index, cell in enumerate(row)]
        lines.append("  ".join(padded).rstrip())
    return lines


def weekday_summary(records):
    counts = [0] * 7
    for _, _, _, weekday in records:
        if weekday is not None:
            counts[weekday] += 1
    lines = []
    for index, count in enumerate(counts):
        if count:
            lines.append("%s: %d date(s)" % (WEEKDAY_NAMES[index], count))
    return lines


def oldest_index(records):
    best = None
    for index, (_, elapsed, _, _) in enumerate(records):
        if elapsed is not None and (best is None or elapsed > records[best][1]):
            best = index
    return best


def main(argv):
    texts = argv[1:] or ["2023-01-01", "2022-12-31", date.today().isoformat()]
    records = collect(texts)
    for line in format_report(records):
        print(line)
    for line in weekday_summary(records):
        print(line)
    best = oldest_index(records)
    if best is None:
        print("no usable dates given")
    else:
        text, elapsed, label, _ = records[best]
        print("oldest date: %s (%s), %d day(s) ago" % (label, text, elapsed))


if __name__ == "__main__":
    main(sys.argv)

