def update_inventory(inventory, item_name, quantity_change):
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name:
        raise ValueError("item_name must be a non-empty string")
    if not isinstance(quantity_change, int) or isinstance(quantity_change, bool):
        raise TypeError("quantity_change must be an integer")
    new_quantity = inventory.get(item_name, 0) + quantity_change
    inventory[item_name] = max(0, new_quantity)
    return inventory


def parse_transaction_line(line):
    parts = [piece.strip() for piece in line.split(",")]
    if len(parts) != 2:
        raise ValueError("expected 'name, change' but got: %r" % line)
    for field_no, piece in enumerate(parts, start=1):
        if not piece:
            raise ValueError("field %d is empty in line: %r" % (field_no, line))
    name, raw_change = parts
    try:
        change = int(raw_change)
    except ValueError:
        raise ValueError("change is not an integer in line: %r" % line)
    return name, change


def parse_transaction_lines(lines):
    transactions = []
    for line_no, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            transactions.append(parse_transaction_line(stripped))
        except ValueError as exc:
            raise ValueError("line %d: %s" % (line_no, exc))
    return transactions


def apply_transactions(inventory, transactions):
    log = []
    for name, change in transactions:
        before = inventory.get(name, 0)
        update_inventory(inventory, name, change)
        log.append((name, before, change, inventory[name]))
    return log


def format_log(log):
    rows = []
    for step, entry in enumerate(log, start=1):
        name, before, change, after = entry
        sign = "+" if change >= 0 else "-"
        rows.append(
            "%2d. %-10s %3d %s%-3d -> %3d" % (step, name, before, sign, abs(change), after)
        )
    return "\n".join(rows)


def format_inventory(inventory):
    names = sorted(inventory)
    rows = []
    for position, name in enumerate(names, start=1):
        rows.append("%2d. %-10s %4d" % (position, name, inventory[name]))
    return "\n".join(rows)


def format_out_of_stock(inventory):
    empty = [name for name in sorted(inventory) if inventory[name] == 0]
    rows = []
    for position, name in enumerate(empty, start=1):
        rows.append("%d) %s" % (position, name))
    return "; ".join(rows)


def main():
    raw_lines = [
        "# name, change",
        "apple, 10",
        "banana, 5",
        "apple, 5",
        "banana, -10",
        "cherry, -3",
        "cherry, 12",
    ]
    inventory = {}
    log = apply_transactions(inventory, parse_transaction_lines(raw_lines))
    print("Transactions:")
    print(format_log(log))
    print("\nFinal inventory:")
