def validate(numbers):
    """Return a list of floats, rejecting non-numeric entries by position."""
    cleaned = []
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"element {index} is not a number: {value!r}")
        cleaned.append(float(value))
    return cleaned


def parse_dataset(text):
    """Turn a whitespace or comma separated line into a list of floats."""
    tokens = text.replace(",", " ").split()
    values = []
    for position, token in enumerate(tokens):
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError(f"token {position} is not numeric: {token!r}")
    return values


def mean(numbers):
    values = validate(numbers)
    if not values:
        return 0.0
    return sum(values) / len(values)


def absolute_deviations(numbers):
    """Absolute distance of every element from the mean, in input order."""
    values = validate(numbers)
    center = mean(values)
    deviations = [0.0] * len(values)
    for index, value in enumerate(values):
        deviations[index] = abs(value - center)
    return deviations


def mean_absolute_deviation(numbers):
    deviations = absolute_deviations(numbers)
    if not deviations:
        return 0.0
    return sum(deviations) / len(deviations)


def format_report(numbers):
    values = validate(numbers)
    center = mean(values)
    deviations = absolute_deviations(values)
    lines = [f"n = {len(values)}, mean = {center:.4f}"]
    for index, spread in enumerate(deviations):
        lines.append(f"  [{index}] {values[index]:8.3f} -> {spread:.4f}")
    lines.append(f"MAD = {mean_absolute_deviation(values):.6f}")
    return "\n".join(lines)


def main():
    raw_datasets = [
        "1 2 3 4",
        "10, 20, 30",
        "",
        "2.5 2.5 2.5 2.5",
