def validate(numbers):
    """Return a list of floats, rejecting non-numeric entries by position."""
    cleaned = []
    for index in range(len(numbers)):
        if isinstance(numbers[index], bool) or not isinstance(numbers[index], (int, float)):
            raise TypeError(f"element {index} is not a number: {numbers[index]!r}")
        cleaned.append(float(numbers[index]))
    return cleaned


def parse_dataset(text):
    """Turn a whitespace or comma separated line into a list of floats."""
    tokens = text.replace(",", " ").split()
    values = []
    for position in range(len(tokens)):
        try:
            values.append(float(tokens[position]))
        except ValueError:
            raise ValueError(f"token {position} is not numeric: {tokens[position]!r}")
    return values


def mean(numbers):
    values = validate(numbers)
    if not values:
        return 0.0
    return sum(values) / len(values)


def absolute_deviations(numbers):
    """Absolute distance of every element from the mean, in input order."""
    values = validate(numbers)
    center = mean(values)
    deviations = [0.0] * len(values)
    for index in range(len(values)):
        deviations[index] = abs(values[index] - center)
    return deviations


def mean_absolute_deviation(numbers):
    deviations = absolute_deviations(numbers)
    if not deviations:
        return 0.0
    return sum(deviations) / len(deviations)


def format_report(numbers):
    values = validate(numbers)
    center = mean(values)
    deviations = absolute_deviations(values)
    lines = [f"n = {len(values)}, mean = {center:.4f}"]
    for index in range(len(deviations)):
        lines.append(f"  [{index}] {values[index]:8.3f} -> {deviations[index]:.4f}")
    lines.append(f"MAD = {mean_absolute_deviation(values):.6f}")
    return "\n".join(lines)


def main():
    raw_datasets = [
        "1 2 3 4",
        "10, 20, 30",
        "",
        "2.5 2.5 2.5 2.5",
        "-5 0 5 10 15",
    ]
    for index in range(len(raw_datasets)):
        values = parse_dataset(raw_datasets[index])
        label = values if values else "(empty)"
        print(f"Dataset {index + 1}: {label}")
        print(format_report(values))
        print()


if __name__ == "__main__":
    main()

