import random

LOW, HIGH = 1, 100


def validate_inputs(target, max_guesses):
    if isinstance(target, bool) or not isinstance(target, int):
        raise TypeError("target must be an integer")
    if isinstance(max_guesses, bool) or not isinstance(max_guesses, int):
        raise TypeError("max_guesses must be an integer")
    if not LOW <= target <= HIGH:
        raise ValueError("target must lie between %d and %d" % (LOW, HIGH))


def play_guessing_game(target, max_guesses):
    validate_inputs(target, max_guesses)
    guesses = [random.randint(LOW, HIGH) for _ in range(max_guesses)]
    for attempt, guess in enumerate(guesses, start=1):
        if guess == target:
            return attempt
    return -1


def run_trials(target, max_guesses, trials):
    return [play_guessing_game(target, max_guesses) for _ in range(trials)]


def summarize(results):
    first_success = None
    for trial, outcome in enumerate(results, start=1):
        if outcome != -1:
            first_success = trial
            break
    wins = [outcome for outcome in results if outcome != -1]
    return {
        "trials": len(results),
        "wins": len(wins),
        "average_guesses": sum(wins) / len(wins) if wins else None,
        "first_success": first_success,
    }


def format_report(target, max_guesses, results, summary):
    lines = ["target=%d, max_guesses=%d" % (target, max_guesses)]
    for trial, outcome in enumerate(results, start=1):
        status = "found on guess %d" % outcome if outcome != -1 else "not found"
        lines.append("  trial %d: %s" % (trial, status))
    lines.append("  wins: %d/%d" % (summary["wins"], summary["trials"]))
    if summary["average_guesses"] is None:
        lines.append("  average guesses: n/a")
    else:
        lines.append("  average guesses: %.2f" % summary["average_guesses"])
    if summary["first_success"] is not None:
        lines.append("  earliest winning trial: %d" % summary["first_success"])
    return "\n".join(lines)


def format_histogram(results, max_guesses):
    counts = [0] * (max_guesses + 1)
    for outcome in results:
        if outcome != -1:
            counts[outcome] += 1
    lines = ["  histogram of winning guess numbers:"]
    for attempt, count in enumerate(counts):
        if attempt and count:
            lines.append("    guess %d: %s" % (attempt, "#" * count))
    return "\n".join(lines)


