            return 0.0

    for i in range(len(sides)):
        for j in range(len(sides)):
            if i == j:
                continue
            for k in range(len(sides)):
                if k == i or k == j:
                    continue
                if sides[i] + sides[j] <= sides[k]:
                    return 0.0

    s = sum(sides) / 2.0

    product_terms = []
    for i in range(len(sides)):
        product_terms.append(s - sides[i])

    product = 1.0
    for i in range(len(product_terms)):
        product *= product_terms[i]

    return math.sqrt(s * product)

