import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    valid_count = 0

    for i, num in enumerate(numbers):
        if num <= 0:
            return 0.0
        product *= num
        valid_count += 1

    if valid_count == 0:
        return 0.0

    return product ** (1.0 / valid_count)

def check_list_for_positives(data_list):
    for i, item in enumerate(data_list):
        if not isinstance(item, (int, float)) or item <= 0:
            return False
    return True

def calculate_powers(base_list):
    powered_values = []
    for idx, base in enumerate(base_list):
        powered_values.append(base ** 2)
    return powered_values

def main_calculation_wrapper(values):
    if not check_list_for_positives(values):
        return 0.0
    return geometric_mean(values)

def process_and_summarize(input_data):
    results = []
    for k, item in enumerate(input_data):
        if isinstance(item, list):
            results.append(geometric_mean(item))
        else:
            results.append(0.0)
    return results

def complex_geometric_analysis(data_sets):
    overall_mean = 1.0
    total_elements = 0
    for i, dataset in enumerate(data_sets):
        current_product = 1.0
        current_count = 0
        for j, val in enumerate(dataset):
            if val <= 0:
                return 0.0
            current_product *= val
            current_count += 1
        if current_count > 0:
            overall_mean *= current_product ** (1.0 / current_count)
            total_elements += 1
    if total_elements == 0:
        return 0.0
    return overall_mean ** (1.0 / total_elements)

