def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False

    at_count = 0
    at_index = -1
    for i, char in enumerate(email_string):
        if char == '@':
            at_count += 1
            at_index = i

    if at_count != 1:
        return False

    if at_index == 0 or at_index == len(email_string) - 1:
        return False

    dot_after_at = False
    for i, char in enumerate(email_string):
        if i > at_index and char == '.':
            dot_after_at = True
            break

    if not dot_after_at:
        return False

    if email_string[at_index + 1] == '.':
        return False

    for i, char in enumerate(email_string):
        if char == ' ':
            return False

    for i, char in enumerate(email_string[:at_index]):
        if not (char.isalnum() or char in "._%+-"):
            return False

    domain_part = email_string[at_index + 1:]
    if not domain_part:
        return False

    for i, char in enumerate(domain_part):
        if not (char.isalnum() or char == '.' or char == '-'):
            return False

    if domain_part[0] == '-' or domain_part[-1] == '-':
        return False

    for i, char in enumerate(domain_part):
        if char == '.' and i == len(domain_part) - 1:
            return False

    for i, char in enumerate(domain_part):
        if char == '.' and domain_part[i+1] == '.':
            return False

    return True

