        dp[0][j] = j

    for i in range(len(s1)):
        char1 = s1[i]
        for j in range(len(s2)):
            char2 = s2[j]
            cost = 0 if char1 == char2 else 1
            dp[i+1][j+1] = min(dp[i][j+1] + 1,        # Deletion
