def rotate_list(lst, n):
    """Return a new list with the elements of lst rotated n positions to the right."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    items = list(lst)
    size = len(items)
    if size == 0:
        return items
    shift = n % size
    rotated = [None] * size
    for index, value in enumerate(items):
        rotated[(index + shift) % size] = value
    return rotated


def rotation_map(lst, n):
    """Map each source index to the (target index, value) pair after rotating by n."""
    size = len(lst)
    if size == 0:
        return {}
    shift = n % size
    mapping = {}
    for index, value in enumerate(lst):
        mapping[index] = ((index + shift) % size, value)
    return mapping


def format_positions(lst):
    """Render a list as 'index:value' pairs for readable reporting."""
    parts = []
    for index, value in enumerate(lst):
        parts.append("{0}:{1}".format(index, value))
    return " ".join(parts) if parts else "(empty)"


def detect_shift(original, rotated):
    """Return the smallest right-rotation turning original into rotated, or None."""
    size = len(original)
    if size != len(rotated):
        return None
    if size == 0:
        return 0
    first = original[0]
    for index, value in enumerate(rotated):
        if value == first and rotate_list(original, index) == rotated:
            return index
    return None


def describe_rotation(lst, n):
    """Build a multi-line description of rotating lst by n."""
    rotated = rotate_list(lst, n)
    lines = ["source   " + format_positions(lst),
             "rotated  " + format_positions(rotated)]
    for source, (target, value) in sorted(rotation_map(lst, n).items()):
        lines.append("  {0!r}: index {1} -> {2}".format(value, source, target))
