def validate_binary(bits):
    if not bits:
        raise ValueError("binary string must not be empty")
    for index, char in enumerate(bits):
        if char not in '01':
            raise ValueError("invalid digit %r at position %d" % (char, index))
    return bits


def binary_to_gray(bits):
    validate_binary(bits)
    gray = []
    for index, char in enumerate(bits):
        if index == 0:
            gray.append(char)
        else:
            gray.append('0' if char == bits[index - 1] else '1')
    return ''.join(gray)


def gray_to_binary(gray):
    validate_binary(gray)
    bits = []
    for index, char in enumerate(gray):
        if index == 0:
            bits.append(char)
        else:
            bits.append('0' if char == bits[index - 1] else '1')
    return ''.join(bits)


def to_int(bits):
    validate_binary(bits)
    value = 0
    for index, char in enumerate(bits):
        if char == '1':
            value += 1 << (len(bits) - 1 - index)
    return value


def differing_positions(left, right):
    if len(left) != len(right):
        raise ValueError("codes must have equal length")
    positions = []
    for index, char in enumerate(left):
        if char != right[index]:
            positions.append(index)
    return positions


def gray_sequence(width):
    return [binary_to_gray(format(value, '0%db' % width)) for value in range(1 << width)]


def format_table(codes):
    lines = []
    for value, code in enumerate(codes):
        lines.append("%3d  %s  %s" % (value, code, gray_to_binary(code)))
    return lines


def main():
    samples = ['000', '1011', '1', '110100']
    for index, bits in enumerate(samples):
        gray = binary_to_gray(bits)
        changed = differing_positions(bits, gray)
        print("%d. binary=%s gray=%s value=%d flipped=%s" % (
            index + 1, bits, gray, to_int(bits), changed or 'none'))

    codes = gray_sequence(3)
    print("3-bit Gray sequence:")
    for line in format_table(codes):
        print(line)

    for index, code in enumerate(codes):
        if index > 0 and len(differing_positions(codes[index - 1], code)) != 1:
            print("adjacency broken between %s and %s" % (codes[index - 1], code))


if __name__ == '__main__':
