def count_set_bits(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("count_set_bits expects an int")
    if n < 0:
        raise ValueError("count_set_bits expects a non-negative int")
    total = 0
    for bit in bin(n)[2:]:
        if bit == "1":
            total += 1
    return total


def set_bit_positions(n):
    """Indices (least significant first) of the bits that are set in n."""
    return [index for index, bit in enumerate(bin(n)[2:][::-1]) if bit == "1"]


def group_bits(binary):
    """Split a binary string into underscore separated groups of four bits."""
    chunks = []
    for index, bit in enumerate(binary[::-1]):
        if index and index % 4 == 0:
            chunks.append("_")
        chunks.append(bit)
    return "".join(reversed(chunks))


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of ints."""
    numbers = []
    for position, token in enumerate(text.replace(",", " ").split()):
        try:
            numbers.append(int(token, 0))
        except ValueError:
            raise ValueError("token %d is not an integer: %r" % (position, token))
    return numbers


def format_row(number, width, binary_width):
    positions = set_bit_positions(number)
    return "%*d  %*s  %2d  %s" % (
        width,
        number,
        binary_width,
        group_bits(bin(number)[2:]),
        count_set_bits(number),
        ",".join(str(p) for p in positions) or "-",
    )


def build_report(numbers):
    width = max((len(str(n)) for n in numbers), default=1)
    binary_width = max((len(group_bits(bin(n)[2:])) for n in numbers), default=6)
    header = "%*s  %*s  %2s  %s" % (width, "n", binary_width, "binary", "on", "bits")
    lines = ["   | " + header]
    for row, number in enumerate(numbers, start=1):
        lines.append("%2d | %s" % (row, format_row(number, width, binary_width)))
    return lines


def bit_frequency(numbers):
    """How often each bit index is set across all the given numbers."""
    counts = [0] * max((n.bit_length() for n in numbers), default=0)
    for number in numbers:
        for index, bit in enumerate(bin(number)[2:][::-1]):
            if bit == "1":
                counts[index] += 1
    return counts


def main():
    numbers = parse_numbers("5 10 0 1 255 1024 4095")
    for line in build_report(numbers):
        print(line)

    print("total set bits: %d" % sum(count_set_bits(n) for n in numbers))

    for index, count in enumerate(bit_frequency(numbers)):
        if count:
            print("bit %2d set in %d of %d numbers" % (index, count, len(numbers)))

    heaviest = max(numbers, key=count_set_bits)
    print("most set bits: %d (%d)" % (heaviest, count_set_bits(heaviest)))


if __name__ == "__main__":
    main()

