def contains_sublist(main_list, sub_list):
    """Return True if sub_list appears as a contiguous block inside main_list."""
    return find_sublist_index(main_list, sub_list) != -1


def find_sublist_index(main_list, sub_list):
    """Return the index of the first contiguous occurrence, or -1 if absent."""
    if not sub_list:
        return 0
    if len(sub_list) > len(main_list):
        return -1
    first = sub_list[0]
    last_start = len(main_list) - len(sub_list)
    for start, value in enumerate(main_list):
        if start > last_start:
            break
        if value != first:
            continue
        if _matches_at(main_list, sub_list, start):
            return start
    return -1


def _matches_at(main_list, sub_list, start):
    """Check whether sub_list lines up with main_list beginning at start."""
    for offset, item in enumerate(sub_list):
        if main_list[start + offset] != item:
            return False
    return True


def find_all_occurrences(main_list, sub_list):
    """Return every start index where sub_list occurs, overlaps included."""
    if not sub_list:
        return list(range(len(main_list) + 1))
    starts = []
    for start in range(len(main_list) - len(sub_list) + 1):
        if _matches_at(main_list, sub_list, start):
            starts.append(start)
    return starts


def describe(main_list, sub_list):
    """Build a one-line human readable summary of the search result."""
    starts = find_all_occurrences(main_list, sub_list)
    if not starts:
        return "%s not contained in %s" % (sub_list, main_list)
    places = ", ".join("#%d@%d" % (rank, start)
                       for rank, start in enumerate(starts))
    return "%s found in %s at %s" % (sub_list, main_list, places)


def main():
    cases = [
        ([1, 2, 3, 4, 5], [2, 3]),
        ([1, 2, 3, 4, 5], [1, 3]),
        ([1, 2, 3, 4, 5], []),
        ([], [7]),
        (list("abcabcab"), list("abc")),
        (["x", "y", "y", "z"], ["y", "y"]),
    ]
    for number, (main_list, sub_list) in enumerate(cases):
        verdict = contains_sublist(main_list, sub_list)
        print("case %d: %s -> %s" % (number, describe(main_list, sub_list), verdict))

    haystack = list("mississippi")
    needle = list("iss")
    hits = find_all_occurrences(haystack, needle)
    print("slices of %s matching %s:" % ("".join(haystack), "".join(needle)))
    for rank, start in enumerate(hits):
        chunk = "".join(haystack[start:start + len(needle)])
        print("  %d) index %d -> %s" % (rank, start, chunk))


if __name__ == "__main__":
    main()

