def validate_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    expected_widths = (4, 2, 2)
    for index, part in enumerate(parts):
        if len(part) != expected_widths[index] or not part.isdigit():
            raise ValueError("bad field %d in date %r" % (index + 1, date_str))
    year, month, day = (int(part) for part in parts)
    if not 1 <= month <= 12:
        raise ValueError("month out of range in %r" % date_str)
    lengths = [31, 29 if year % 4 == 0 and (year % 100 or year % 400 == 0) else 28,
               31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if not 1 <= day <= lengths[month - 1]:
        raise ValueError("day out of range in %r" % date_str)
    return year, month, day


def parse_entries(text):
    lines = text.splitlines()
    entries = []
    for lineno, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        fields = stripped.split(None, 1)
        if len(fields) != 2:
            raise ValueError("line %d needs a date and a description: %r" % (lineno, line))
        entries.append((fields[0], fields[1]))
    return entries


def add_calendar_event(calendar, date_str, event_description):
    validate_date(date_str)
    description = event_description.strip()
    if not description:
        raise ValueError("event description must not be empty")
    calendar.setdefault(date_str, []).append(description)


def add_many(calendar, entries):
    added = 0
    for position, entry in enumerate(entries):
        try:
            date_str, description = entry
        except (TypeError, ValueError):
            raise ValueError("entry %d is not a (date, description) pair" % position)
        add_calendar_event(calendar, date_str, description)
        added += 1
    return added


def busiest_dates(calendar):
    if not calendar:
        return []
    ranked = sorted(calendar.items(), key=lambda item: (-len(item[1]), item[0]))
    top = len(ranked[0][1])
    return [date_str for date_str, events in ranked if len(events) == top]


def format_calendar(calendar):
    dates = sorted(calendar)
    lines = []
    for position, date_str in enumerate(dates, start=1):
        events = calendar[date_str]
        lines.append("%d) %s (%d event%s)" % (position, date_str, len(events),
                                              "" if len(events) == 1 else "s"))
        for number, description in enumerate(events, start=1):
            lines.append("   %d. %s" % (number, description))
    return "\n".join(lines)


def main():
    schedule = """
    2023-10-27 Dentist
    2023-02-28 Payroll review
    2023-10-27 Code review
    2023-10-27 Gym
    """
    cal = {}
    add_calendar_event(cal, '2023-10-26', 'Meeting')
    add_calendar_event(cal, '2023-10-26', 'Lunch')
    print("loaded %d extra events" % add_many(cal, parse_entries(schedule)))
    print(format_calendar(cal))
    print("busiest: %s" % ", ".join(busiest_dates(cal)))


if __name__ == '__main__':
    main()

