def calculate_hamming_distance(s1, s2):
    """Count the positions at which s1 and s2 hold different characters."""
    distance = 0
    for index in range(len(s1)):
        if s1[index] != s2[index]:
            distance += 1
    return distance


def alignment_marks(s1, s2):
    """Build a caret/space line marking the differing columns."""
    marks = []
    for index in range(len(s1)):
        marks.append('^' if s1[index] != s2[index] else ' ')
    return ''.join(marks)


def describe_mismatches(s1, s2):
    """Describe each mismatch as 'at <index>: <a> -> <b>'."""
    descriptions = []
    for index in range(len(s1)):
        if s1[index] != s2[index]:
            descriptions.append("at %d: %s -> %s" % (index, s1[index], s2[index]))
    return descriptions


def check_equal_length(pairs):
    """Raise ValueError naming the first pair whose strings differ in length."""
    for number in range(len(pairs)):
        if len(pairs[number][0]) != len(pairs[number][1]):
            raise ValueError(
                "pair at index %d: lengths %d and %d differ"
                % (number, len(pairs[number][0]), len(pairs[number][1]))
            )


def format_report(s1, s2):
    """Produce a multi-line report for one pair of strings."""
    lines = [s1, s2, alignment_marks(s1, s2)]
    lines.append("distance = %d" % calculate_hamming_distance(s1, s2))
    descriptions = describe_mismatches(s1, s2)
    for number in range(len(descriptions)):
        lines.append("  %d) %s" % (number + 1, descriptions[number]))
    return '\n'.join(lines)


def main():
