def merge_dicts(d1, d2):
    """Return a new dict with d2's values winning on shared keys."""
    merged = dict(d1)
    for key, value in d2.items():
        merged[key] = value
    return merged


def merge_all(dicts):
    """Fold a sequence of dictionaries left to right."""
    result = {}
    for position, current in enumerate(dicts):
        if not isinstance(current, dict):
            raise TypeError("argument %d is not a dict: %r" % (position, current))
        result = merge_dicts(result, current)
    return result


def find_conflicts(dicts):
    """Map each repeated key to the list of (index, value) pairs that set it."""
    seen = {}
    for index, current in enumerate(dicts):
        for key, value in current.items():
            seen.setdefault(key, []).append((index, value))
    return {key: pairs for key, pairs in seen.items() if len(pairs) > 1}


def format_conflict(key, pairs):
    parts = []
    for rank, (index, value) in enumerate(pairs):
        arrow = "->" if rank == len(pairs) - 1 else "  "
        parts.append("%s dict[%d]=%r" % (arrow, index, value))
    return "%-6s %s" % (key, " ".join(parts))


def report(dicts):
    """Build a human readable summary of a merge over several dictionaries."""
    lines = []
    for index, current in enumerate(dicts):
        lines.append("input %d: %r" % (index, current))
    merged = merge_all(dicts)
    lines.append("merged : %r" % (merged,))
    conflicts = find_conflicts(dicts)
    if conflicts:
        lines.append("conflicts (last value wins):")
        for key in sorted(conflicts):
            lines.append("  " + format_conflict(key, conflicts[key]))
    else:
        lines.append("conflicts: none")
    return "\n".join(lines)


def main():
    cases = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
        ({'host': 'localhost', 'port': 80}, {'port': 8080, 'debug': True}),
